window.QB_TKP_B11 = [
{id:"TKP-1621", q:"Anda CPNS di puskesmas. Seorang balita dari keluarga perantau belum terdaftar di posyandu karena orang tuanya tidak memiliki KTP setempat, dan kader ragu melayaninya. Sikap Anda ....", opts:[{t:"Menegaskan bahwa pelayanan kesehatan tidak boleh menolak balita, lalu membantu mencatatkan data sementara sambil mengurus administrasinya", s:5},{t:"Meminta kader melayani balita tersebut terlebih dahulu, kemudian membantu orang tuanya mengurus surat domisili", s:4},{t:"Menyarankan orang tua mengurus KTP setempat dulu sebelum anaknya bisa dilayani posyandu", s:3},{t:"Meneruskan masalah ini ke atasan dan menunggu keputusan resmi sebelum bertindak", s:2},{t:"Mengikuti keraguan kader karena aturan administrasi memang mensyaratkan KTP setempat", s:1}], ex:"Pelayanan kesehatan bersifat universal; menolak balita karena administrasi bertentangan dengan prinsip pelayanan publik yang inklusif."},
{id:"TKP-1622", q:"Anda petugas perpustakaan daerah. Seorang pelajar SMP ingin meminjam buku tetapi tidak memiliki kartu anggota, hanya kartu pelajar. Tindakan Anda ....", opts:[{t:"Membantu membuatkan kartu anggota gratis di tempat dengan kartu pelajar sebagai identitas, lalu meminjamkan bukunya", s:5},{t:"Mengizinkan meminjam dengan mencatat identitas dari kartu pelajar sebagai jaminan sementara", s:4},{t:"Menyuruh pelajar tersebut membaca di tempat saja karena belum menjadi anggota resmi", s:3},{t:"Meminta pelajar kembali lain waktu setelah mengurus kartu anggota di kelurahan", s:2},{t:"Menolak meminjamkan karena aturan keanggotaan tidak boleh dilanggar", s:1}], ex:"Mempermudah akses literasi bagi pelajar adalah wujud pelayanan publik yang adaptif; kartu pelajar cukup sebagai identitas awal."},
{id:"TKP-1623", q:"Anda petugas piket malam di kecamatan. Seorang warga datang mengurus izin keramaian hajatan yang akan digelar lusa, padahal pengurusan normalnya siang hari. Sikap Anda ....", opts:[{t:"Melayani pengurusan izin tersebut malam itu juga selama syarat lengkap, karena hajatan tidak bisa ditunda", s:5},{t:"Menerima berkasnya dan berjanji memproses pagi harinya agar warga tidak perlu bolak-balik", s:4},{t:"Meminta warga datang kembali besok pagi sesuai jam layanan normal", s:3},{t:"Menolak karena pengurusan izin bukan wewenang petugas piket malam", s:2},{t:"Menyuruh warga mengurus ke polsek saja tanpa membantu", s:1}], ex:"Petugas piket tetap bagian dari pelayanan; melayani kebutuhan mendesak warga menunjukkan responsivitas."},
{id:"TKP-1624", q:"Anda petugas dukcapil. Seorang ibu ingin membuatkan akta kelahiran anaknya, tetapi dokumen ayah tidak lengkap karena ayah bekerja sebagai TKI di luar negeri. Tindakan Anda ....", opts:[{t:"Memproses akta dengan dokumen yang ada dan mencatatkan keterangan ayah sesuai ketentuan, sambil menjelaskan cara melengkapi kemudian", s:5},{t:"Menerima permohonan dan memberi daftar dokumen pengganti yang bisa disiapkan, misalnya surat keterangan dari desa", s:4},{t:"Menunda penerbitan sampai dokumen ayah lengkap agar data valid", s:3},{t:"Menyarankan ibu menunggu ayah pulang dari luar negeri", s:2},{t:"Menolak permohonan karena syarat administrasi tidak terpenuhi", s:1}], ex:"Hak anak atas identitas hukum tidak boleh terhambat kondisi orang tua; petugas wajib mencari jalan keluar administratif."},
{id:"TKP-1625", q:"Anda honorer di kelurahan. Seorang pelaku UMKM meminta surat keterangan domisili usaha untuk pengajuan KUR, tetapi satu berkas pendukung kurang. Sikap Anda ....", opts:[{t:"Membantu menerbitkan surat dengan catatan, lalu mendampingi melengkapi berkas kurang agar pengajuan KUR tidak tertunda", s:5},{t:"Menerbitkan surat keterangan sementara sambil memberi tenggat melengkapi berkas pendukung", s:4},{t:"Meminta pelaku usaha melengkapi berkas dulu sebelum surat diterbitkan", s:3},{t:"Menolak menerbitkan karena berkas tidak lengkap", s:2},{t:"Menyuruh pelaku usaha mengurus ke notaris saja", s:1}], ex:"Mendukung UMKM berarti mempercepat, bukan menghambat; pendampingan melengkapi berkas adalah solusi terbaik."},
{id:"TKP-1626", q:"Seorang pelaku usaha kecil ingin mengurus sertifikasi halal tetapi tidak paham prosedur daringnya. Anda petugas pendamping di dinas koperasi. Tindakan Anda ....", opts:[{t:"Mendampingi langkah demi langkah pengisian daring sampai pengajuan terkirim, lalu memberi nomor kontak untuk konsultasi lanjutan", s:5},{t:"Membuatkan panduan tertulis sederhana dan membantu mengisi bagian yang sulit", s:4},{t:"Mengarahkan ke situs resmi dan memintanya mencoba sendiri di rumah", s:3},{t:"Menyarankan memakai jasa konsultan berbayar agar cepat", s:2},{t:"Menolak membantu karena pendampingan teknis bukan tugas dinas", s:1}], ex:"Pendampingan aktif memastikan pelaku usaha kecil tidak tertinggal digitalisasi layanan."},
{id:"TKP-1627", q:"Seorang orang tua siswa penerima KIP tidak tahu cara mengaktivasi dana bantuan di bank. Anda petugas di sekolah. Sikap Anda ....", opts:[{t:"Menghubungi orang tua, menjelaskan prosedurnya, dan mendampingi ke bank jika diperlukan sampai dana bisa digunakan", s:5},{t:"Memberi penjelasan tertulis langkah aktivasi dan nomor layanan bank yang bisa dihubungi", s:4},{t:"Meminta orang tua bertanya langsung ke bank", s:3},{t:"Menunggu orang tua datang sendiri ke sekolah untuk bertanya", s:2},{t:"Menganggap itu urusan bank, bukan urusan sekolah", s:1}], ex:"Dana bantuan harus benar-benar sampai ke penerima; sekolah bertanggung jawab memastikan orang tua memahami prosedurnya."},
{id:"TKP-1628", q:"Anda petugas administrasi puskesmas. Seorang pasien membutuhkan surat rujukan BPJS hari ini juga, tetapi poli tujuan sudah penuh. Tindakan Anda ....", opts:[{t:"Mencarikan alternatif faskes rujukan terdekat yang masih menerima, mengurus suratnya, dan menjelaskan alurnya ke pasien", s:5},{t:"Menghubungi poli tujuan untuk menanyakan kemungkinan slot tambahan karena kondisi pasien mendesak", s:4},{t:"Menerbitkan rujukan dengan jadwal kontrol minggu depan", s:3},{t:"Meminta pasien mencari sendiri rumah sakit yang masih menerima", s:2},{t:"Menolak menerbitkan rujukan karena poli sudah penuh", s:1}], ex:"Keselamatan pasien di atas keterbatasan administratif; mencarikan alternatif adalah bentuk tanggung jawab pelayanan."},
{id:"TKP-1629", q:"Anda diminta menerbitkan surat keterangan tidak mampu untuk beasiswa, tetapi ada tetangga yang meragukan kondisi ekonomi pemohon. Sikap Anda ....", opts:[{t:"Melakukan verifikasi faktual ke lapangan secara objektif, lalu menerbitkan surat sesuai hasil verifikasi yang sebenarnya", s:5},{t:"Meminta data pendukung tambahan dari pemohon sebelum memutuskan", s:4},{t:"Menunda penerbitan sampai ada kesepakatan warga", s:3},{t:"Menolak menerbitkan karena ada keberatan tetangga", s:2},{t:"Menerbitkan begitu saja tanpa verifikasi demi cepat", s:1}], ex:"Keputusan administrasi harus berbasis verifikasi faktual, bukan desas-desus; itulah integritas pelayanan."},
{id:"TKP-1630", q:"Keluarga yang berduka ingin memakamkan jenazah malam hari di TPU, di luar jam layanan normal. Anda petugas administrasi pemakaman. Tindakan Anda ....", opts:[{t:"Mengoordinasikan petugas dan membuka layanan khusus malam itu karena pemakaman tidak dapat ditunda", s:5},{t:"Menghubungi petugas lapangan untuk membantu proses pemakaman dengan administrasi menyusul pagi harinya", s:4},{t:"Meminta keluarga menunggu sampai pagi sesuai jam layanan", s:3},{t:"Menolak karena di luar jam kerja", s:2},{t:"Menyuruh keluarga mengurus sendiri tanpa pendampingan petugas", s:1}], ex:"Pelayanan kedukaan bersifat darurat kemanusiaan; fleksibilitas jam layanan adalah wujud empati birokrasi."},
{id:"TKP-1631", q:"Seorang warga mengajukan izin usaha peternakan ayam, tetapi warga sekitar memprotes karena khawatir bau dan lalat. Anda petugas perizinan. Sikap Anda ....", opts:[{t:"Memfasilitasi musyawarah antara pemohon dan warga untuk menyepakati syarat teknis, misalnya jarak kandang dan pengelolaan limbah, sebelum izin diterbitkan", s:5},{t:"Melakukan survei lokasi dan menetapkan syarat teknis yang harus dipenuhi pemohon", s:4},{t:"Menunda izin sampai protes warga mereda", s:3},{t:"Menolak izin karena ada penolakan warga", s:2},{t:"Menerbitkan izin begitu saja karena syarat formal terpenuhi", s:1}], ex:"Perizinan yang baik menyeimbangkan kepentingan usaha dan kenyamanan warga melalui musyawarah dan syarat teknis."},
{id:"TKP-1632", q:"Nelayan tradisional memprotes aturan baru surat izin memancing di waduk yang dinilai memberatkan. Anda petugas dinas perikanan. Tindakan Anda ....", opts:[{t:"Menampung aspirasi nelayan, mensosialisasikan maksud aturan, dan mengusulkan penyederhanaan prosedur ke pimpinan", s:5},{t:"Menjelaskan tujuan aturan untuk kelestarian waduk dan membantu nelayan mengurus izinnya", s:4},{t:"Meminta nelayan mematuhi aturan yang sudah ditetapkan", s:3},{t:"Mengabaikan protes karena aturan sudah sah", s:2},{t:"Menindak nelayan yang tidak berizin tanpa sosialisasi", s:1}], ex:"Regulasi yang baik lahir dari dialog; menampung aspirasi sambil mensosialisasikan adalah jalan tengah yang profesional."},
{id:"TKP-1633", q:"Layanan keliling e-KTP menyambangi sebuah SMA. Beberapa siswa kelas 12 belum berusia 17 tahun tetapi membutuhkan KIA untuk pendaftaran kuliah. Sikap Anda sebagai petugas ....", opts:[{t:"Melayani perekaman e-KTP bagi yang sudah cukup umur dan menerbitkan KIA bagi yang belum, sehingga semua kebutuhan terpenuhi", s:5},{t:"Menjelaskan perbedaan e-KTP dan KIA lalu memproses sesuai kategori umur masing-masing siswa", s:4},{t:"Hanya melayani yang sudah berusia 17 tahun", s:3},{t:"Meminta siswa yang belum cukup umur menunggu tahun depan", s:2},{t:"Menolak melayani siswa karena layanan keliling hanya untuk e-KTP", s:1}], ex:"Petugas yang memahami seluruh produk layanan administrasi dapat memberi solusi tepat untuk tiap kebutuhan warga."},
{id:"TKP-1634", q:"Seorang warga melapor menjadi korban parkir liar dengan tarif tidak wajar di kawasan pasar. Anda petugas dinas perhubungan. Tindakan Anda ....", opts:[{t:"Mencatat laporan, menerjunkan tim ke lokasi untuk penertiban, dan menginformasikan tindak lanjutnya kepada pelapor", s:5},{t:"Mengoordinasikan dengan pengelola pasar untuk menertibkan juru parkir liar", s:4},{t:"Mencatat laporan untuk dibahas dalam rapat internal", s:3},{t:"Menyarankan warga parkir di tempat resmi saja lain kali", s:2},{t:"Mengabaikan laporan karena pelapor tidak punya bukti", s:1}], ex:"Setiap laporan warga wajib ditindaklanjuti dengan tindakan nyata dan umpan balik, bukan sekadar dicatat."},
{id:"TKP-1635", q:"Layanan SIM keliling diserbu pemohon hingga antrean membludak, lalu sistem daring tiba-tiba offline. Anda koordinator lapangan. Sikap Anda ....", opts:[{t:"Mengumumkan kondisi secara terbuka, memberi nomor antrean manual yang adil, dan memprioritaskan lansia serta yang sudah menunggu lama", s:5},{t:"Mengatur ulang antrean secara manual sambil menunggu sistem pulih", s:4},{t:"Meminta pemohon pulang dan kembali besok", s:3},{t:"Melayani siapa yang paling dekat dengan loket saja", s:2},{t:"Membubarkan antrean tanpa penjelasan", s:1}], ex:"Keterbukaan informasi dan pengaturan antrean yang adil menjaga kepercayaan publik saat sistem bermasalah."},
{id:"TKP-1636", q:"Dua kelompok ahli waris yang berselisih masing-masing meminta diterbitkan surat keterangan ahli waris versi mereka. Anda petugas kelurahan. Tindakan Anda ....", opts:[{t:"Menolak menerbitkan surat sepihak, memfasilitasi musyawarah keluarga, dan menerbitkan surat hanya atas kesepakatan atau penetapan pengadilan", s:5},{t:"Menjelaskan bahwa kelurahan tidak berwenang memutuskan sengketa waris dan menyarankan jalur musyawarah atau pengadilan", s:4},{t:"Menerbitkan surat untuk pihak yang datang lebih dulu", s:3},{t:"Menerbitkan dua surat berbeda sesuai permintaan masing-masing", s:2},{t:"Menolak semua permohonan tanpa penjelasan", s:1}], ex:"Aparatur tidak boleh menjadi alat salah satu pihak yang bersengketa; netralitas dan jalur hukum adalah solusinya."},
{id:"TKP-1637", q:"Pengajuan izin pendirian rumah ibadah mendapat keberatan dari sebagian warga sekitar. Anda pejabat yang menangani. Sikap Anda ....", opts:[{t:"Memfasilitasi dialog antara pemohon dan warga dengan melibatkan FKUB untuk mencari kesepakatan sesuai regulasi", s:5},{t:"Menjelaskan persyaratan perizinan rumah ibadah secara transparan kepada kedua belah pihak", s:4},{t:"Menunda proses izin sampai tidak ada keberatan", s:3},{t:"Menolak izin demi menghindari konflik", s:2},{t:"Menerbitkan izin diam-diam tanpa melibatkan warga", s:1}], ex:"Kebebasan beribadah dijamin konstitusi; peran aparatur adalah memediasi keberagaman melalui forum resmi seperti FKUB."},
{id:"TKP-1638", q:"Warga sebuah desa meminta prioritas perbaikan jalan rusak karena sudah banyak kecelakaan. Anggaran terbatas dan banyak usulan lain. Anda di dinas PU. Tindakan Anda ....", opts:[{t:"Melakukan survei tingkat kerusakan dan urgensi semua usulan, lalu menyusun skala prioritas berbasis data yang transparan", s:5},{t:"Mengusulkan perbaikan bertahap dimulai dari ruas paling rusak sambil mencari sumber pendanaan tambahan", s:4},{t:"Memasukkan usulan ke daftar tunggu tahun anggaran berikutnya", s:3},{t:"Meminta warga bersabar tanpa penjelasan", s:2},{t:"Memprioritaskan usulan dari desa yang punya kedekatan dengan pejabat", s:1}], ex:"Alokasi anggaran infrastruktur harus berbasis data kerusakan dan urgensi, bukan kedekatan politik."},
{id:"TKP-1639", q:"Seorang pelanggan PDAM protes karena tagihan air melonjak tiga kali lipat padahal pemakaian normal. Anda petugas layanan pelanggan. Sikap Anda ....", opts:[{t:"Memeriksa riwayat meter dan kemungkinan kebocoran, lalu mengoreksi tagihan jika terbukti kesalahan pencatatan", s:5},{t:"Menjadwalkan pemeriksaan meter ke rumah pelanggan dan memberi penjelasan tertulis", s:4},{t:"Meminta pelanggan tetap membayar dulu, keberatan diproses kemudian", s:3},{t:"Menyatakan meter sudah benar tanpa pemeriksaan", s:2},{t:"Mengabaikan protes karena sistem tidak mungkin salah", s:1}], ex:"Keberatan pelanggan wajib diverifikasi faktual; koreksi atas kesalahan pencatatan adalah hak pelanggan."},
{id:"TKP-1640", q:"Sampah menumpuk di sebuah kawasan karena warga membuang sembarangan dan armada pengangkut terbatas. Anda lurah setempat. Tindakan Anda ....", opts:[{t:"Menggerakkan kerja bakti warga, menambah jadwal angkut sementara, dan mensosialisasikan sanksi buang sampah sembarangan", s:5},{t:"Berkonsultasi dengan dinas kebersihan untuk penambahan armada dan titik kontainer", s:4},{t:"Memasang spanduk larangan buang sampah", s:3},{t:"Menunggu dinas kebersihan bertindak", s:2},{t:"Menyalahkan warga yang tidak disiplin", s:1}], ex:"Pemimpin wilayah harus menggerakkan solusi kolektif, bukan menunggu atau menyalahkan."},
{id:"TKP-1641", q:"Seorang orang tua protes karena anaknya tidak diterima di sekolah negeri padahal rumahnya dekat, akibat sistem zonasi. Anda panitia PPDB. Sikap Anda ....", opts:[{t:"Menjelaskan cara kerja sistem zonasi secara terbuka, menunjukkan data jarak, dan membantu mencarikan alternatif sekolah", s:5},{t:"Memverifikasi ulang data jarak domisili untuk memastikan tidak ada kesalahan input", s:4},{t:"Meminta orang tua menerima hasil sistem", s:3},{t:"Menyarankan pindah ke sekolah swasta", s:2},{t:"Menolak menjelaskan dengan alasan sistem sudah final", s:1}], ex:"Transparansi cara kerja sistem dan bantuan alternatif meredam keberatan warga secara adil."},
{id:"TKP-1642", q:"Penyaluran bansos sembako dinilai tidak tepat sasaran dan warga memprotes di balai desa. Anda perangkat desa. Tindakan Anda ....", opts:[{t:"Membuka data penerima untuk diverifikasi bersama warga, memperbaiki data yang salah, dan melaporkan ke dinas sosial", s:5},{t:"Melakukan pendataan ulang dengan melibatkan RT/RW dan tokoh masyarakat", s:4},{t:"Menjelaskan bahwa data berasal dari pusat dan tidak bisa diubah", s:3},{t:"Meminta warga yang protes bersabar", s:2},{t:"Menyembunyikan data penerima agar tidak ramai", s:1}], ex:"Keterbukaan data dan verifikasi partisipatif adalah kunci memulihkan kepercayaan dalam penyaluran bansos."},
{id:"TKP-1643", q:"Dalam vaksinasi massal, sejumlah lansia takut divaksin karena termakan isu hoaks. Anda nakes di puskesmas. Tindakan Anda ....", opts:[{t:"Mendatangi para lansia, menjelaskan dengan bahasa sederhana dan sabar, serta memberi contoh lansia yang sudah divaksin dan sehat", s:5},{t:"Menggandeng tokoh agama dan tokoh masyarakat untuk ikut menyosialisasikan keamanan vaksin", s:4},{t:"Membagikan brosur informasi tentang vaksin", s:3},{t:"Membiarkan saja karena vaksinasi bersifat sukarela", s:2},{t:"Memaksa lansia divaksin demi target cakupan", s:1}], ex:"Edukasi persuasif dengan pendekatan tokoh yang dipercaya lebih efektif daripada paksaan dalam mengatasi hoaks kesehatan."},
{id:"TKP-1644", q:"Sebuah keluarga menolak didata dalam pendataan stunting karena merasa malu. Anda kader kesehatan. Sikap Anda ....", opts:[{t:"Menjelaskan dengan empati bahwa pendataan bersifat rahasia dan bertujuan membantu anak mendapat intervensi gizi, bukan memberi label", s:5},{t:"Meminta bantuan tokoh yang dihormati keluarga untuk membujuk", s:4},{t:"Mencatat keluarga tersebut sebagai menolak dan melanjutkan ke rumah lain", s:3},{t:"Melaporkan keluarga tersebut sebagai tidak kooperatif", s:2},{t:"Memaksa pendataan dengan ancaman sanksi", s:1}], ex:"Pendekatan empatik yang menjamin kerahasiaan data membuka pintu kerja sama keluarga."},
{id:"TKP-1645", q:"Program makan bergizi gratis di sebuah sekolah kekurangan relawan untuk distribusi harian. Anda koordinator program di dinas. Tindakan Anda ....", opts:[{t:"Menggandeng komite sekolah, karang taruna, dan orang tua murid dalam jadwal relawan bergilir yang terorganisir", s:5},{t:"Berkonsultasi dengan pihak sekolah untuk mengatur ulang mekanisme distribusi yang lebih efisien", s:4},{t:"Meminta guru merangkap sebagai relawan distribusi", s:3},{t:"Mengurangi frekuensi distribusi karena keterbatasan SDM", s:2},{t:"Membiarkan distribusi berjalan seadanya", s:1}], ex:"Melibatkan komunitas dalam jadwal terorganisir memastikan program berjalan tanpa membebani satu pihak."},
{id:"TKP-1646", q:"Warga menuntut transparansi penggunaan dana desa melalui papan informasi yang tidak pernah diperbarui. Anda sekretaris desa. Sikap Anda ....", opts:[{t:"Segera memperbarui papan informasi, mempublikasikan laporan realisasi, dan membuka forum tanya jawab dengan warga", s:5},{t:"Menyusun laporan penggunaan dana dan menempelkannya di balai desa", s:4},{t:"Menjelaskan secara lisan kepada perwakilan warga", s:3},{t:"Berjanji akan diperbarui setelah audit selesai", s:2},{t:"Menolak membuka data dengan alasan rahasia desa", s:1}], ex:"Dana desa adalah uang publik; keterbukaan informasi adalah kewajiban, bukan pilihan."},
{id:"TKP-1647", q:"Seorang warga membutuhkan surat keterangan usaha malam hari untuk pengajuan modal yang tenggatnya besok pagi. Anda honorer piket di kelurahan. Tindakan Anda ....", opts:[{t:"Membantu menerbitkan surat sesuai prosedur yang berlaku dan memintakan tanda tangan pejabat berwenang yang bisa dihubungi", s:5},{t:"Menerima berkas dan berjanji mengurusnya pagi-pagi sekali sebelum tenggat", s:4},{t:"Meminta warga datang pagi hari sesuai jam layanan", s:3},{t:"Menolak karena honorer tidak berwenang menerbitkan surat", s:2},{t:"Menyuruh warga mencari kelurahan lain", s:1}], ex:"Inisiatif membantu dalam koridor prosedur menunjukkan dedikasi pelayanan meski status honorer."},
{id:"TKP-1648", q:"Seorang konsumen melapor menemukan banyak barang kedaluwarsa di sebuah pasar swalayan. Anda petugas dinas perdagangan. Tindakan Anda ....", opts:[{t:"Menindaklanjuti dengan inspeksi mendadak, mengamankan barang kedaluwarsa, dan menindak tegas sesuai ketentuan", s:5},{t:"Mengoordinasikan tim pengawas untuk pemeriksaan ke lokasi terlapor", s:4},{t:"Mencatat laporan dan mengirim surat teguran ke swalayan", s:3},{t:"Menyarankan konsumen tidak berbelanja di sana lagi", s:2},{t:"Mengabaikan karena tidak ada korban keracunan", s:1}], ex:"Perlindungan konsumen menuntut tindakan nyata di lapangan, bukan sekadar teguran administratif."},
{id:"TKP-1649", q:"Satpol PP akan menertibkan PKL di trotoar, tetapi para pedagang memohon karena itu satu-satunya mata pencaharian. Anda camat setempat. Sikap Anda ....", opts:[{t:"Memfasilitasi relokasi ke lokasi binaan yang layak dengan masa transisi, sebelum penertiban dilakukan", s:5},{t:"Berkonsultasi dengan dinas koperasi untuk menyiapkan tempat usaha alternatif", s:4},{t:"Menunda penertiban sampai ada solusi", s:3},{t:"Tetap menertibkan sesuai aturan tanpa solusi", s:2},{t:"Membiarkan PKL tetap di trotoar agar tidak gaduh", s:1}], ex:"Penegakan aturan harus dibarengi solusi mata pencaharian; relokasi yang manusiawi adalah jalan tengah terbaik."},
{id:"TKP-1650", q:"Seorang warga difabel tidak bisa datang ke kantor untuk mengurus dokumen karena keterbatasan fisik. Anda petugas layanan. Tindakan Anda ....", opts:[{t:"Mengatur layanan kunjungan ke rumah warga tersebut dan menyelesaikan pengurusannya di tempat", s:5},{t:"Menawarkan layanan via telepon atau daring dengan pendampingan penuh", s:4},{t:"Meminta keluarga warga datang sebagai wakil", s:3},{t:"Meminta warga berusaha datang dengan bantuan tetangga", s:2},{t:"Menolak melayani karena pemohon harus hadir sendiri", s:1}], ex:"Pelayanan inklusif mendatangi warga yang berkebutuhan khusus, bukan sebaliknya."},
{id:"TKP-1651", q:"Ambulans desa hanya satu unit. Dua permintaan datang bersamaan: pasien gawat darurat dan pasien kontrol rutin. Anda pengelola ambulans. Keputusan Anda ....", opts:[{t:"Memprioritaskan pasien gawat darurat, menjelaskan kepada keluarga pasien kontrol, dan membantu mencarikan transportasi alternatif", s:5},{t:"Menghubungi puskesmas untuk meminta bantuan ambulans cadangan", s:4},{t:"Melayani yang meminta lebih dulu", s:3},{t:"Meminta kedua keluarga berunding sendiri", s:2},{t:"Menolak salah satunya tanpa penjelasan", s:1}], ex:"Prioritas medis gawat darurat tidak bisa ditawar; komunikasi empatik kepada pihak lain mencegah konflik."},
{id:"TKP-1652", q:"Keluarga yang berduka membutuhkan surat keterangan kematian segera untuk klaim asuransi, tetapi sistem pencatatan sedang gangguan. Anda petugas kelurahan. Tindakan Anda ....", opts:[{t:"Menerbitkan surat keterangan manual resmi yang ditandatangani lurah, lalu menginput ke sistem setelah pulih", s:5},{t:"Membuatkan surat pengantar sementara yang diakui pihak asuransi", s:4},{t:"Meminta keluarga menunggu sampai sistem pulih", s:3},{t:"Menolak menerbitkan karena data belum terinput", s:2},{t:"Menyuruh keluarga mengurus ke dukcapil kabupaten", s:1}], ex:"Kebutuhan mendesak keluarga duka harus dilayani dengan solusi manual resmi, bukan menunggu sistem."},
{id:"TKP-1653", q:"Antrean legalisir ijazah di dinas pendidikan membludak dan Anda satu-satunya petugas yang masuk hari itu. Sikap Anda ....", opts:[{t:"Tetap melayani dengan tertib, mengatur antrean bernomor, dan meminta bantuan petugas unit lain untuk verifikasi", s:5},{t:"Mempercepat proses dengan menyederhanakan langkah yang tidak esensial tanpa mengorbankan ketelitian", s:4},{t:"Melayani seadanya dan meminta sisanya kembali besok", s:3},{t:"Menutup layanan lebih awal karena kewalahan", s:2},{t:"Membiarkan antrean tanpa pengaturan", s:1}], ex:"Keterbatasan personel bukan alasan menurunkan kualitas; pengaturan antrean dan kolaborasi adalah solusinya."},
{id:"TKP-1654", q:"Sepasang calon pengantin mendaftar nikah di KUA, tetapi mempelai perempuan belum cukup umur menurut ketentuan. Anda penghulu. Tindakan Anda ....", opts:[{t:"Menjelaskan syarat usia perkawinan sesuai UU, menolak pencatatan, dan mengarahkan ke prosedur dispensasi pengadilan jika mendesak", s:5},{t:"Menunda pencatatan sambil memberi penjelasan tentang perlindungan anak", s:4},{t:"Mencatatkan dengan syarat ada surat pernyataan orang tua", s:3},{t:"Mencatatkan saja demi membantu warga", s:2},{t:"Menerima imbalan agar pencatatan tetap jalan", s:1}], ex:"Perlindungan anak di atas segalanya; petugas wajib menegakkan batas usia perkawinan sesuai undang-undang."},
{id:"TKP-1655", q:"Dalam program PTSL, batas tanah yang diukur bersengketa dengan tetangga yang mengklaim sebagian. Anda anggota tim ukur. Sikap Anda ....", opts:[{t:"Menghentikan pengukuran bidang sengketa, membuat berita acara sengketa resmi, memfasilitasi mediasi dengan melibatkan perangkat desa, dan melanjutkan hanya setelah ada kesepakatan tertulis atau putusan pengadilan", s:5},{t:"Menghentikan pengukuran bidang sengketa, mencatat sebagai sengketa, dan memfasilitasi mediasi sebelum sertifikat diterbitkan", s:4},{t:"Mengukur sesuai pengakuan pemohon dan mencatat keberatan tetangga", s:3},{t:"Membatalkan seluruh pengukuran di desa tersebut", s:2},{t:"Memihak pemohon yang lebih dulu mendaftar", s:1}], ex:"Sertifikat tidak boleh diterbitkan di atas sengketa; mediasi adalah langkah wajib sebelum pengukuran dilanjutkan."},
{id:"TKP-1656", q:"Seorang pengusaha memasang reklame besar tanpa izin di jalan protokol. Anda petugas penertiban. Tindakan Anda ....", opts:[{t:"Memberi teguran tertulis dengan tenggat pengurusan izin atau pembongkaran, lalu menindak tegas jika diabaikan", s:5},{t:"Mendatangi pengusaha dan menjelaskan prosedur perizinan reklame", s:4},{t:"Langsung membongkar tanpa pemberitahuan", s:3},{t:"Membiarkan karena pengusaha berpengaruh", s:2},{t:"Meminta uang damai agar reklame boleh tetap terpasang", s:1}], ex:"Penegakan diawali teguran resmi dan tenggat wajar; ketegasan tanpa prosedur justru melemahkan legitimasi."},
{id:"TKP-1657", q:"Warga melaporkan titik api kebakaran hutan melalui telepon darurat. Anda petugas piket. Tindakan Anda ....", opts:[{t:"Segera meneruskan laporan ke tim pemadam dengan titik koordinat lengkap, lalu mengabari pelapor bahwa tim meluncur", s:5},{t:"Mencatat detail laporan dan menghubungi posko terdekat", s:4},{t:"Meminta warga memastikan dulu apinya besar atau tidak", s:3},{t:"Menunggu laporan kedua sebelum bertindak", s:2},{t:"Mengabaikan karena musim kemarau laporan palsu sering terjadi", s:1}], ex:"Setiap laporan kebakaran hutan harus direspons cepat; verifikasi dilakukan tim di lapangan, bukan menunda respons."},
{id:"TKP-1658", q:"Distribusi logistik korban banjir dinilai tidak merata; beberapa dusun belum menerima bantuan. Anda koordinator posko. Tindakan Anda ....", opts:[{t:"Memetakan ulang seluruh titik pengungsian, menyusun jadwal distribusi berkeadilan, dan mempublikasikan progresnya", s:5},{t:"Mengirim tim pendataan ke dusun yang belum terjangkau", s:4},{t:"Meminta warga dusun tersebut datang ke posko induk", s:3},{t:"Membagi rata sisa logistik yang ada seadanya", s:2},{t:"Menyalahkan relawan yang tidak melaporkan", s:1}], ex:"Distribusi bencana harus berbasis pemetaan kebutuhan, bukan siapa yang paling dekat dengan posko."},
{id:"TKP-1659", q:"Layanan SIM keliling dijadwalkan ke sebuah pulau kecil, tetapi kapal penyeberangan batal karena cuaca buruk. Anda koordinator. Sikap Anda ....", opts:[{t:"Mengumumkan penundaan secara terbuka ke warga pulau, menjadwal ulang secepatnya, dan memprioritaskan mereka yang sudah mendaftar", s:5},{t:"Mencari alternatif transportasi yang aman jika memungkinkan", s:4},{t:"Membatalkan tanpa pemberitahuan", s:3},{t:"Meminta warga pulau datang ke kota sendiri", s:2},{t:"Tetap berangkat memaksa meski cuaca buruk", s:1}], ex:"Keselamatan di atas jadwal; komunikasi terbuka dan penjadwalan ulang menjaga kepercayaan warga terpencil."},
{id:"TKP-1660", q:"Aduan warga melalui kanal LAPOR! belum ditindaklanjuti selama dua minggu dan pelapor menagih janji. Anda admin pengaduan. Tindakan Anda ....", opts:[{t:"Menelusuri status aduan, menghubungi unit terkait untuk percepatan, dan memberi penjelasan jujur beserta estimasi tindak lanjut kepada pelapor", s:5},{t:"Meneruskan aduan ke unit terkait dengan prioritas tinggi", s:4},{t:"Meminta pelapor bersabar karena antrean panjang", s:3},{t:"Menutup aduan dengan status selesai agar statistik bagus", s:2},{t:"Mengabaikan tagihan pelapor", s:1}], ex:"Kanal pengaduan hanya bermakna jika ada tindak lanjut nyata dan komunikasi jujur kepada pelapor."},
{id:"TKP-1661", q:"Seorang warga membutuhkan surat pengantar SKCK malam ini juga untuk melamar pekerjaan yang tenggatnya besok. Anda petugas kelurahan. Tindakan Anda ....", opts:[{t:"Membantu menerbitkan surat pengantar sesuai prosedur malam itu juga karena menyangkut mata pencaharian warga", s:5},{t:"Menerima berkas dan berkoordinasi dengan pejabat untuk tanda tangan pagi-pagi sekali", s:4},{t:"Meminta warga datang besok pagi", s:3},{t:"Menolak karena pengantar SKCK bukan urusan mendesak", s:2},{t:"Meminta imbalan jasa cepat", s:1}], ex:"Mata pencaharian warga adalah kebutuhan mendesak; pelayanan responsif dalam koridor prosedur adalah kewajiban."},
{id:"TKP-1662", q:"Berkas seorang warga tercecer antar meja di layanan satu pintu sehingga permohonannya tertunda. Anda petugas yang mengetahuinya. Sikap Anda ....", opts:[{t:"Meminta maaf kepada warga, melacak berkas sampai ketemu, dan memastikan permohonannya diprioritaskan", s:5},{t:"Membantu warga membuat salinan berkas pengganti tanpa biaya tambahan", s:4},{t:"Meminta warga melengkapi ulang berkasnya", s:3},{t:"Menyalahkan petugas meja lain", s:2},{t:"Menganggap itu risiko biasa dalam pelayanan", s:1}], ex:"Kesalahan internal instansi tidak boleh dibebankan ke warga; tanggung jawab memperbaikinya ada pada petugas."},
{id:"TKP-1663", q:"Seorang turis asing kebingungan mencari informasi wisata dan petugas yang ada tidak fasih berbahasa Inggris. Anda staf dinas pariwisata. Tindakan Anda ....", opts:[{t:"Berinisiatif membantu dengan aplikasi penerjemah dan bahasa isyarat sederhana sampai turis memahami informasi yang dibutuhkan", s:5},{t:"Menghubungkan turis dengan pemandu atau staf yang bisa berbahasa Inggris", s:4},{t:"Memberi brosur berbahasa Inggris dan berharap cukup", s:3},{t:"Meminta turis mencari informasi sendiri di internet", s:2},{t:"Mengabaikan karena bukan tugas utama", s:1}], ex:"Keramahan kepada wisatawan adalah wajah daerah; keterbatasan bahasa diatasi dengan inisiatif, bukan diabaikan."},
{id:"TKP-1664", q:"Seorang warga memperpanjang STNK tetapi hanya membawa fotokopi BPKB karena yang asli dijadikan jaminan bank. Anda petugas Samsat. Tindakan Anda ....", opts:[{t:"Menerima fotokopi yang dilegalisir disertai surat keterangan jaminan dari bank sebagai pengganti sesuai ketentuan", s:5},{t:"Menjelaskan alternatif dokumen pengganti yang sah dan membantu prosesnya", s:4},{t:"Menolak dan meminta BPKB asli", s:3},{t:"Meminta warga menebus BPKB dulu", s:2},{t:"Memproses dengan imbalan tambahan", s:1}], ex:"Petugas yang memahami ketentuan dokumen pengganti dapat memberi solusi sah tanpa melanggar aturan."},
{id:"TKP-1665", q:"Sebuah yayasan sosial meminta surat keterangan domisili untuk pengajuan bantuan. Berkasnya lengkap. Anda petugas kelurahan. Tindakan Anda ....", opts:[{t:"Segera memproses dan menerbitkan surat karena yayasan sosial melayani kepentingan publik", s:5},{t:"Memverifikasi cepat keberadaan yayasan lalu menerbitkan surat", s:4},{t:"Memproses sesuai antrean normal tanpa prioritas", s:3},{t:"Menunda karena yayasan bukan warga perorangan", s:2},{t:"Meminta sumbangan untuk percepatan", s:1}], ex:"Lembaga sosial yang melayani publik layak mendapat kemudahan; verifikasi cepat tetap diperlukan."},
{id:"TKP-1666", q:"Seorang warga keberatan karena NJOP tanahnya naik sehingga PBB melonjak. Anda petugas pajak daerah. Sikap Anda ....", opts:[{t:"Menjelaskan dasar penetapan NJOP, menunjukkan data pembanding, dan menginformasikan prosedur keberatan resmi", s:5},{t:"Membantu warga mengajukan keberatan sesuai mekanisme yang berlaku", s:4},{t:"Meminta warga membayar dulu, keberatan kemudian", s:3},{t:"Menyatakan penetapan sudah final tidak bisa diganggu gugat", s:2},{t:"Menawarkan keringanan dengan imbalan", s:1}], ex:"Keberatan pajak adalah hak wajib pajak; petugas wajib menjelaskan dasar dan mekanisme keberatan secara transparan."},
{id:"TKP-1667", q:"Dua kubu peserta pemilu meminta jadwal kampanye di lapangan yang sama pada hari yang sama. Anda petugas perizinan. Tindakan Anda ....", opts:[{t:"Mengatur jadwal bergantian secara adil dan transparan berdasarkan aturan, serta menginformasikan ke kedua kubu", s:5},{t:"Berkonsultasi dengan Bawaslu untuk penentuan jadwal yang netral", s:4},{t:"Memberi izin kepada yang mengajukan lebih dulu", s:3},{t:"Memberi izin kepada kubu yang didukung atasan", s:2},{t:"Menolak keduanya agar aman", s:1}], ex:"Netralitas aparatur dalam pemilu diwujudkan melalui pengaturan yang adil dan transparan bagi semua peserta."},
{id:"TKP-1668", q:"Puskesmas mengadakan layanan kesehatan keliling ke panti lansia, tetapi sebagian lansia menolak diperiksa. Anda nakes. Sikap Anda ....", opts:[{t:"Mendekati dengan sabar, mengobrol santai dulu untuk membangun kepercayaan, baru menawarkan pemeriksaan", s:5},{t:"Meminta bantuan pengurus panti untuk membujuk para lansia", s:4},{t:"Hanya memeriksa yang bersedia", s:3},{t:"Mencatat sebagai menolak dan pulang", s:2},{t:"Memaksa pemeriksaan demi target program", s:1}], ex:"Lansia butuh pendekatan personal yang membangun kepercayaan; paksaan justru merusak tujuan pelayanan kesehatan."},
{id:"TKP-1669", q:"Seorang pelamar CPNS membutuhkan surat keterangan belum menikah yang tenggatnya besok. Berkas lengkap. Anda petugas kelurahan. Tindakan Anda ....", opts:[{t:"Segera memproses dan menerbitkan surat hari itu juga karena menyangkut masa depan pelamar", s:5},{t:"Memproses dengan prioritas dan menghubungi pelamar saat sudah bisa diambil", s:4},{t:"Memproses sesuai antrean normal", s:3},{t:"Meminta pelamar datang minggu depan", s:2},{t:"Meminta biaya percepatan", s:1}], ex:"Pelayanan yang berpihak pada masa depan warga, terutama yang berkasnya lengkap, menunjukkan keberpihakan birokrasi."},
{id:"TKP-1670", q:"Seorang guru honorer mengadu insentifnya terlambat tiga bulan. Anda staf dinas pendidikan. Tindakan Anda ....", opts:[{t:"Menelusuri penyebab keterlambatan, memberi penjelasan jujur, dan mengupayakan percepatan pencairan", s:5},{t:"Mengoordinasikan dengan bagian keuangan untuk kepastian jadwal pencairan", s:4},{t:"Meminta guru honorer bersabar", s:3},{t:"Menyalahkan proses administrasi yang panjang", s:2},{t:"Mengabaikan karena honorer bukan prioritas", s:1}], ex:"Kesejahteraan guru honorer adalah tanggung jawab dinas; menelusuri dan mempercepat pencairan adalah wujud keberpihakan."},
{id:"TKP-1671", q:"Dua atasan Anda memberi perintah yang bertentangan mengenai prioritas pekerjaan minggu ini. Sikap Anda ....", opts:[{t:"Mengonfirmasi ke kedua atasan secara terbuka untuk menyelaraskan prioritas, lalu menjalankan hasil kesepakatan", s:5},{t:"Meminta arahan tertulis dari atasan langsung sebagai penanggung jawab utama", s:4},{t:"Mengerjakan perintah atasan yang jabatannya lebih tinggi", s:3},{t:"Mengerjakan keduanya setengah-setengah", s:2},{t:"Mengabaikan salah satu perintah diam-diam", s:1}], ex:"Konflik perintah diselesaikan melalui konfirmasi terbuka, bukan tebak-tebakan atau kepatuhan buta."},
{id:"TKP-1672", q:"Anda menerima limpahan berkas dari pejabat lama dan menemukan banyak yang cacat prosedur. Atasan meminta Anda membereskannya diam-diam. Sikap Anda ....", opts:[{t:"Mendokumentasikan temuan cacat prosedur secara resmi, melaporkannya, dan mengusulkan perbaikan sesuai ketentuan", s:5},{t:"Memperbaiki yang bisa diperbaiki sambil mencatat temuan untuk arsip", s:4},{t:"Membereskan diam-diam sesuai perintah atasan", s:3},{t:"Membiarkan berkas cacat apa adanya", s:2},{t:"Menyembunyikan temuan agar tidak jadi masalah", s:1}], ex:"Temuan cacat prosedur wajib didokumentasikan dan dilaporkan; menutupinya justru menciptakan risiko hukum baru."},
{id:"TKP-1673", q:"Atasan meminta Anda memundurkan tanggal surat keputusan agar terlihat terbit tepat waktu. Sikap Anda ....", opts:[{t:"Menolak dengan sopan dan menjelaskan bahwa pemalsuan tanggal dokumen adalah pelanggaran hukum", s:5},{t:"Mengusulkan menerbitkan surat dengan tanggal sebenarnya disertai penjelasan keterlambatan", s:4},{t:"Meminta perintah tertulis dulu sebelum melaksanakan", s:3},{t:"Melaksanakan karena perintah atasan", s:2},{t:"Melaksanakan dan merahasiakannya", s:1}], ex:"Integritas berarti menolak perintah yang melanggar hukum, sehalus apa pun kemasannya."},
{id:"TKP-1674", q:"Saat stock opname, satu unit laptop inventaris kantor tidak ditemukan. Anda penanggung jawab aset. Tindakan Anda ....", opts:[{t:"Melaporkan kehilangan secara resmi, menelusuri jejak peminjaman, dan mengusulkan penggantian sesuai ketentuan", s:5},{t:"Membuat berita acara kehilangan dan berkonsultasi dengan atasan untuk langkah selanjutnya", s:4},{t:"Menutupi dengan meminjam laptop pribadi saat pemeriksaan", s:3},{t:"Menyalahkan petugas sebelumnya", s:2},{t:"Membiarkan dan berharap tidak ketahuan audit", s:1}], ex:"Kehilangan aset negara wajib dilaporkan resmi dan ditelusuri; menutupi hanya memperbesar masalah."},
{id:"TKP-1675", q:"Anda mengetahui mobil dinas sering dipakai atasan untuk keperluan pribadi di akhir pekan. Sikap Anda ....", opts:[{t:"Menyampaikan keberatan melalui mekanisme resmi, misalnya ke inspektorat atau atasan yang lebih tinggi, dengan bukti", s:5},{t:"Mengingatkan atasan secara pribadi bahwa penggunaan mobil dinas diatur ketentuan", s:4},{t:"Mencatat saja sebagai arsip pribadi", s:3},{t:"Membiarkan karena bukan urusan Anda", s:2},{t:"Ikut memanfaatkan mobil dinas untuk pribadi", s:1}], ex:"Penyalahgunaan fasilitas negara harus dilaporkan melalui jalur resmi; pembiaran adalah bentuk pembenaran."},
{id:"TKP-1676", q:"Atasan meminta dana pelatihan dialihkan untuk membiayai rapat yang anggarannya habis. Sikap Anda sebagai bendahara ....", opts:[{t:"Menolak pengalihan karena menyalahi peruntukan anggaran, dan mengusulkan pengajuan revisi resmi jika memang mendesak", s:5},{t:"Menjelaskan aturan penggunaan anggaran kepada atasan dan meminta keputusan tertulis", s:4},{t:"Mengalihkan sebagian kecil saja", s:3},{t:"Mengalihkan sesuai perintah atasan", s:2},{t:"Mengalihkan dan memanipulasi laporannya", s:1}], ex:"Anggaran negara terikat peruntukan; pengalihan tanpa revisi resmi adalah pelanggaran disiplin anggaran."},
{id:"TKP-1677", q:"Seorang vendor mengirim parsel mewah ke rumah Anda di akhir tahun setelah proyeknya selesai. Sikap Anda ....", opts:[{t:"Mengembalikan parsel tersebut dan menjelaskan bahwa Anda tidak menerima gratifikasi dalam bentuk apa pun", s:5},{t:"Melaporkan penerimaan parsel ke atasan atau unit pengendalian gratifikasi", s:4},{t:"Menerima tetapi tidak memengaruhi keputusan kerja", s:3},{t:"Menerima dan membagikannya ke tetangga", s:2},{t:"Menerima karena proyek sudah selesai jadi tidak ada konflik", s:1}], ex:"Gratifikasi tetap gratifikasi meski proyek selesai; pengembalian dan pelaporan adalah sikap yang benar."},
{id:"TKP-1678", q:"Seorang saudara meminta Anda merekomendasikannya bekerja di instansi tanpa mengikuti seleksi. Sikap Anda ....", opts:[{t:"Menolak dengan tegas dan menjelaskan bahwa semua penerimaan harus melalui seleksi terbuka yang adil", s:5},{t:"Mengarahkan saudara untuk mengikuti seleksi resmi dan membantu persiapan", s:4},{t:"Berjanji membantu jika ada lowongan", s:3},{t:"Menyelipkan namanya ke panitia", s:2},{t:"Memalsukan dokumen pendukungnya", s:1}], ex:"Nepotisme merusak meritokrasi; membantu yang benar adalah mengarahkan ke jalur seleksi resmi."},
{id:"TKP-1679", q:"Seseorang menawarkan bocoran soal ujian dinas dengan imbalan uang. Sikap Anda ....", opts:[{t:"Menolak dan melaporkan penawaran tersebut ke panitia atau inspektorat", s:5},{t:"Menolak tawaran dan memperingatkan rekan lain agar tidak tergiur", s:4},{t:"Menolak tetapi tidak melaporkan", s:3},{t:"Mempertimbangkan karena butuh kenaikan pangkat", s:2},{t:"Menerima tawaran tersebut", s:1}], ex:"Kecurangan dalam ujian dinas merusak integritas korps; menolak sekaligus melaporkan adalah kewajiban."},
{id:"TKP-1680", q:"Dalam seleksi internal, salah satu peserta adalah keponakan Anda sendiri. Anda menjadi anggota panitia. Sikap Anda ....", opts:[{t:"Menyatakan konflik kepentingan dan mengundurkan diri dari penilaian peserta tersebut", s:5},{t:"Meminta panitia lain yang menilai keponakan Anda", s:4},{t:"Tetap menilai dengan objektif", s:3},{t:"Memberi nilai sedikit lebih tinggi secara diam-diam", s:2},{t:"Memastikan keponakan Anda lolos", s:1}], ex:"Konflik kepentingan harus dinyatakan terbuka dan dihindari; klaim objektivitas pribadi tidak cukup."},
{id:"TKP-1681", q:"Anda diminta menandatangani berita acara serah terima pekerjaan yang belum sempat Anda periksa kebenarannya. Sikap Anda ....", opts:[{t:"Menolak menandatangani sebelum memeriksa, dan meminta waktu untuk verifikasi faktual", s:5},{t:"Menandatangani dengan catatan perlu verifikasi susulan", s:4},{t:"Menandatangani karena diminta atasan", s:3},{t:"Menandatangani tanpa membaca", s:2},{t:"Meminta orang lain yang menandatangani", s:1}], ex:"Tanda tangan adalah pertanggungjawaban hukum; menandatangani tanpa verifikasi adalah kecerobohan profesional."},
{id:"TKP-1682", q:"Anda mengetahui teman sekantor memanipulasi data laporan, dan ia meminta Anda tutup mulut. Sikap Anda ....", opts:[{t:"Melaporkan manipulasi data melalui jalur resmi seperti atasan atau whistleblowing system", s:5},{t:"Menegur teman dan mendesaknya memperbaiki data sebelum dilaporkan", s:4},{t:"Diam karena tidak ingin merusak pertemanan", s:3},{t:"Ikut menutupi demi solidaritas", s:2},{t:"Memanfaatkan informasi itu untuk menekan teman", s:1}], ex:"Loyalitas pada kebenaran dan negara di atas pertemanan; manipulasi data harus dilaporkan resmi."},
{id:"TKP-1683", q:"Usaha sampingan Anda mulai menyita jam kerja dinas karena banyak pesanan. Sikap Anda ....", opts:[{t:"Menata ulang waktu usaha di luar jam dinas dan memastikan kinerja kantor tidak terganggu", s:5},{t:"Mengurangi porsi usaha sampingan sampai beban kerja kantor normal kembali", s:4},{t:"Mengerjakan usaha di sela jam istirahat saja", s:3},{t:"Tetap menjalankan keduanya apa adanya", s:2},{t:"Menggunakan fasilitas kantor untuk usaha sampingan", s:1}], ex:"Pekerjaan negara adalah prioritas utama; usaha sampingan tidak boleh mengganggu kinerja dinas."},
{id:"TKP-1684", q:"Anda menyadari ada klaim ganda uang perjalanan dinas yang Anda ajukan karena kesalahan input. Sikap Anda ....", opts:[{t:"Segera melaporkan ke bendahara dan mengembalikan kelebihan pembayaran", s:5},{t:"Membuat surat pernyataan koreksi dan memproses pengembalian resmi", s:4},{t:"Mendiamkan karena kesalahan sistem, bukan kesengajaan", s:3},{t:"Menganggap sebagai rezeki", s:2},{t:"Mengulangi kesalahan serupa di kesempatan lain", s:1}], ex:"Kelebihan pembayaran negara wajib dikembalikan meski karena kesalahan; kejujuran tidak menunggu ketahuan."},
{id:"TKP-1685", q:"Seorang rekan mengajak Anda memalsukan absensi kehadiran agar terlihat disiplin. Sikap Anda ....", opts:[{t:"Menolak tegas dan mengingatkan bahwa pemalsuan absensi adalah pelanggaran disiplin", s:5},{t:"Menolak ajakan dan menjaga absensi sendiri tetap jujur", s:4},{t:"Menolak tetapi tidak menegur", s:3},{t:"Ikut sekali saja karena terpaksa", s:2},{t:"Menerima ajakan tersebut", s:1}], ex:"Disiplin dimulai dari kejujuran kehadiran; ajakan memalsukan harus ditolak tegas."},
{id:"TKP-1686", q:"Seorang rekanan menyerahkan kwitansi yang nilainya digelembungkan untuk proyek kecil di unit Anda. Sikap Anda ....", opts:[{t:"Menolak kwitansi tersebut dan meminta kwitansi sesuai nilai sebenarnya, serta melaporkan ke atasan", s:5},{t:"Mengembalikan kwitansi dan meminta perbaikan dokumen", s:4},{t:"Menerima tetapi tidak memprosesnya", s:3},{t:"Memproses karena nilainya kecil", s:2},{t:"Menyetujui dan membagi selisihnya", s:1}], ex:"Penggelembungan nilai sekecil apa pun adalah korupsi; penolakan dan pelaporan adalah satu-satunya sikap benar."},
{id:"TKP-1687", q:"Anda memegang kartu kredit kantor untuk operasional, dan ada kebutuhan pribadi mendesak. Sikap Anda ....", opts:[{t:"Tidak menggunakannya sama sekali untuk keperluan pribadi dan mencari solusi lain", s:5},{t:"Menggunakannya lalu segera mengganti sebelum pemeriksaan", s:4},{t:"Menggunakannya untuk kebutuhan kecil saja", s:3},{t:"Menggunakannya karena akan diganti nanti", s:2},{t:"Menggunakannya dan memanipulasi laporannya", s:1}], ex:"Dana operasional kantor tidak boleh disentuh untuk pribadi dalam kondisi apa pun."},
{id:"TKP-1688", q:"Anda dilibatkan menyusun spesifikasi pengadaan dan ada arahan agar spesifikasinya hanya cocok untuk satu vendor tertentu. Sikap Anda ....", opts:[{t:"Menolak arahan dan menyusun spesifikasi yang adil, terbuka, dan berbasis kebutuhan", s:5},{t:"Menyusun spesifikasi umum lalu melaporkan arahan tersebut ke atasan", s:4},{t:"Mengikuti arahan karena perintah pimpinan", s:3},{t:"Mengikuti arahan diam-diam", s:2},{t:"Meminta imbalan dari vendor yang diuntungkan", s:1}], ex:"Spesifikasi yang diarahkan merusak persaingan sehat; penolakan adalah wujud integritas pengadaan."},
{id:"TKP-1689", q:"Saat mengisi penilaian kinerja mandiri, ada godaan menaikkan nilai agar terlihat berprestasi. Sikap Anda ....", opts:[{t:"Mengisi sesuai fakta dan bukti kerja yang sebenarnya", s:5},{t:"Mengisi objektif meski hasilnya tidak maksimal", s:4},{t:"Menaikkan sedikit agar tidak kalah dari rekan", s:3},{t:"Menaikkan banyak demi promosi", s:2},{t:"Meminta rekan saling menaikkan nilai", s:1}], ex:"Penilaian kinerja yang jujur adalah dasar pengembangan karier yang sehat."},
{id:"TKP-1690", q:"Saat WFH, tidak ada yang mengawasi dan ada godaan bermalas-malasan. Sikap Anda ....", opts:[{t:"Tetap bekerja disiplin sesuai target dan melaporkan progres secara berkala", s:5},{t:"Menyusun jadwal kerja mandiri dan menaatinya", s:4},{t:"Bekerja seadanya yang penting laporan terisi", s:3},{t:"Bermalas-malasan karena tidak diawasi", s:2},{t:"Memalsukan laporan kegiatan harian", s:1}], ex:"Integritas justru diuji saat tidak diawasi; disiplin WFH menunjukkan profesionalisme sejati."},
{id:"TKP-1691", q:"Sebuah toko memberi Anda diskon khusus besar-besaran karena tahu Anda pejabat pengadaan. Sikap Anda ....", opts:[{t:"Menolak diskon khusus tersebut dan berbelanja dengan harga normal seperti konsumen lain", s:5},{t:"Melaporkan tawaran tersebut ke unit pengendalian gratifikasi", s:4},{t:"Menerima karena dianggap rezeki", s:3},{t:"Menerima dan merahasiakannya", s:2},{t:"Meminta diskon lebih besar", s:1}], ex:"Diskon khusus karena jabatan adalah gratifikasi terselubung; penolakan adalah sikap yang tepat."},
{id:"TKP-1692", q:"Sebuah perusahaan bermasalah menawarkan sponsorship besar untuk acara kantor Anda. Sikap Anda ....", opts:[{t:"Menolak sponsorship dan mengusulkan mencari sponsor yang bersih agar nama instansi tidak tercemar", s:5},{t:"Berkonsultasi dengan pimpinan tentang risiko reputasi sebelum memutuskan", s:4},{t:"Menerima karena acara butuh dana", s:3},{t:"Menerima diam-diam", s:2},{t:"Menerima dan memberi imbalan proyek", s:1}], ex:"Reputasi instansi lebih berharga dari dana acara; sponsor bermasalah membawa risiko konflik kepentingan."},
{id:"TKP-1693", q:"Penyedia katering acara kantor menawarkan kickback agar kontraknya diperpanjang. Sikap Anda ....", opts:[{t:"Menolak dan melaporkan tawaran tersebut melalui jalur resmi", s:5},{t:"Menolak tawaran dan mengevaluasi katering secara objektif", s:4},{t:"Menolak tetapi tidak melaporkan", s:3},{t:"Mempertimbangkan karena butuh uang", s:2},{t:"Menerima tawaran itu", s:1}], ex:"Kickback dalam pengadaan sekecil apa pun adalah korupsi; tolak dan laporkan."},
{id:"TKP-1694", q:"Seorang pelapor pelanggaran meminta identitasnya dirahasiakan karena takut diintimidasi. Anda petugas yang menerima laporan. Sikap Anda ....", opts:[{t:"Menjamin kerahasiaan identitas pelapor sesuai ketentuan dan memproses laporan secara profesional", s:5},{t:"Menyimpan identitas pelapor terpisah dari berkas laporan", s:4},{t:"Menjanjikan rahasia tetapi mencatat di berkas umum", s:3},{t:"Membocorkan identitas ke atasan", s:2},{t:"Menolak laporan tanpa identitas jelas", s:1}], ex:"Perlindungan pelapor adalah prasyarat berfungsinya sistem pengawasan internal."},
{id:"TKP-1695", q:"Anda menemukan kesalahan perhitungan tunjangan yang membuat Anda menerima lebih besar dari seharusnya. Sikap Anda ....", opts:[{t:"Segera melaporkan ke bagian keuangan dan mengembalikan kelebihan tersebut", s:5},{t:"Membuat laporan tertulis tentang kesalahan hitung untuk dikoreksi", s:4},{t:"Mendiamkan karena bukan kesalahan Anda", s:3},{t:"Menikmati kelebihan tersebut", s:2},{t:"Berharap kesalahan serupa terulang", s:1}], ex:"Kelebihan pembayaran yang tidak menjadi hak wajib dikembalikan; kejujuran finansial adalah fondasi integritas."},
{id:"TKP-1696", q:"Atasan mempresentasikan hasil kerja tim ke pimpinan tetapi hanya menyebut namanya sendiri. Anda anggota tim. Sikap Anda ....", opts:[{t:"Menyampaikan keberatan secara profesional melalui forum yang tepat dan meminta pengakuan kontribusi tim", s:5},{t:"Mendokumentasikan kontribusi tim untuk arsip kinerja", s:4},{t:"Diam karena takut dimusuhi atasan", s:3},{t:"Menyebarluaskan kekecewaan ke rekan lain", s:2},{t:"Membalas dengan mengklaim hasil kerja atasan", s:1}], ex:"Kredit kerja tim harus diakui; menyampaikannya lewat jalur profesional lebih tepat daripada diam atau bergosip."},
{id:"TKP-1697", q:"Atasan meminta Anda menjadi saksi yang mendukung versinya dalam pemeriksaan internal, padahal Anda tahu versinya tidak benar. Sikap Anda ....", opts:[{t:"Menolak dan menyampaikan kesaksian sesuai fakta yang sebenarnya", s:5},{t:"Meminta untuk tidak dilibatkan sebagai saksi", s:4},{t:"Memberi kesaksian netral yang ambigu", s:3},{t:"Mendukung versi atasan demi karier", s:2},{t:"Membuat kesaksian palsu", s:1}], ex:"Kesaksian palsu adalah pelanggaran hukum; kebenaran tidak bisa ditawar demi loyalitas buta."},
{id:"TKP-1698", q:"Pekerjaan Anda menumpuk karena kebiasaan menunda-nunda, dan tenggat tinggal dua hari. Sikap Anda ....", opts:[{t:"Menyusun prioritas, fokus menyelesaikan yang paling mendesak, dan lembur secara bertanggung jawab", s:5},{t:"Meminta bantuan rekan untuk bagian yang bisa didelegasikan", s:4},{t:"Mengerjakan seadanya yang penting terkumpul", s:3},{t:"Meminta perpanjangan tenggat tanpa alasan kuat", s:2},{t:"Menyalin pekerjaan orang lain agar cepat selesai", s:1}], ex:"Tanggung jawab atas keterlambatan sendiri diselesaikan dengan kerja ekstra, bukan jalan pintas."},
{id:"TKP-1699", q:"Karena jabatan, Anda memiliki akses ke pangkalan data kependudukan. Seorang teman meminta data tetangganya untuk urusan pribadi. Sikap Anda ....", opts:[{t:"Menolak tegas karena data kependudukan dilindungi undang-undang dan hanya untuk kepentingan dinas", s:5},{t:"Menjelaskan aturan perlindungan data pribadi kepada teman", s:4},{t:"Memberi sebagian data yang dianggap tidak sensitif", s:3},{t:"Memberi data karena teman dekat", s:2},{t:"Memberi data dengan imbalan", s:1}], ex:"Data pribadi warga dilindungi UU; penyalahgunaan akses adalah pelanggaran serius."},
{id:"TKP-1700", q:"Seseorang menawarkan jabatan strategis kepada Anda dengan syarat membayar sejumlah uang. Sikap Anda ....", opts:[{t:"Menolak dan melaporkan penawaran tersebut ke aparat penegak hukum atau inspektorat", s:5},{t:"Menolak tawaran dan mencatat identitas penawar untuk dilaporkan", s:4},{t:"Menolak tetapi tidak melaporkan", s:3},{t:"Mempertimbangkan karena peluang langka", s:2},{t:"Menerima tawaran tersebut", s:1}], ex:"Jual beli jabatan adalah korupsi; menolak sekaligus melaporkan melindungi integritas birokrasi."},
{id:"TKP-1701", q:"Ada tekanan dari pihak politik agar Anda memprioritaskan pendukungnya dalam penyaluran bantuan. Sikap Anda ....", opts:[{t:"Menolak tekanan dan menyalurkan bantuan sesuai data dan kriteria yang objektif", s:5},{t:"Melaporkan tekanan tersebut ke atasan atau Bawaslu", s:4},{t:"Menunda penyaluran sampai tekanan mereda", s:3},{t:"Mengikuti sebagian tekanan agar aman", s:2},{t:"Memprioritaskan pendukung pihak tersebut", s:1}], ex:"Netralitas ASN harga mati; bantuan publik harus berbasis data, bukan afiliasi politik."},
{id:"TKP-1702", q:"Anda diminta membuat laporan kegiatan fiktif untuk menyerap sisa anggaran akhir tahun. Sikap Anda ....", opts:[{t:"Menolak dan mengusulkan pengembalian sisa anggaran atau kegiatan riil yang bermanfaat", s:5},{t:"Melaporkan permintaan tersebut ke atasan yang lebih tinggi", s:4},{t:"Membuat laporan seadanya tanpa kegiatan nyata", s:3},{t:"Membuat laporan fiktif sesuai perintah", s:2},{t:"Membuat laporan fiktif dan mengambil dananya", s:1}], ex:"Laporan fiktif adalah pemalsuan dokumen negara; sisa anggaran lebih baik dikembalikan daripada dikorupsi."},
{id:"TKP-1703", q:"Seorang rekan memplagiat laporan yang Anda susun dan mengklaimnya sebagai karyanya. Sikap Anda ....", opts:[{t:"Menyampaikan keberatan dengan bukti kepemilikan karya melalui jalur yang profesional", s:5},{t:"Berdiskusi langsung dengan rekan tersebut meminta pengakuan yang jujur", s:4},{t:"Membiarkan karena tidak ingin ribut", s:3},{t:"Menyebarkan isu bahwa rekan itu plagiat", s:2},{t:"Membalas memplagiat karya rekan lain", s:1}], ex:"Karya intelektual harus dihargai; penyelesaian profesional dengan bukti lebih tepat daripada diam atau balas dendam."},
{id:"TKP-1704", q:"Anda diminta lembur tanpa uang lembur untuk mengejar tenggat pekerjaan penting. Sikap Anda ....", opts:[{t:"Bersedia lembur demi tanggung jawab, sambil mengusulkan pencatatan resmi agar hak tetap diperjuangkan", s:5},{t:"Bersedia lembur dan mendiskusikan kompensasi kemudian", s:4},{t:"Menolak lembur karena tidak ada uang lembur", s:3},{t:"Lembur tetapi bekerja setengah hati", s:2},{t:"Pulang dan membiarkan tenggat terlewat", s:1}], ex:"Tanggung jawab pada tugas penting di atas perhitungan sempit, namun hak tetap diperjuangkan lewat jalur resmi."},
{id:"TKP-1705", q:"Seorang kerabat meminta Anda membocorkan soal ujian seleksi internal yang Anda ketahui. Sikap Anda ....", opts:[{t:"Menolak tegas dan menjelaskan bahwa pembocoran soal adalah pelanggaran berat", s:5},{t:"Menolak dan mengarahkan kerabat untuk belajar dengan sungguh-sungguh", s:4},{t:"Menolak tetapi tidak menjelaskan", s:3},{t:"Memberi kisi-kisi secara umum", s:2},{t:"Membocorkan soal tersebut", s:1}], ex:"Integritas seleksi harus dijaga; membantu kerabat yang benar adalah mendorongnya belajar, bukan curang."},
{id:"TKP-1706", q:"Sebuah dokumen penting hilang dari meja Anda menjelang audit. Tindakan Anda ....", opts:[{t:"Segera melaporkan kehilangan, menelusuri salinan atau arsip digital, dan membuat berita acara resmi", s:5},{t:"Mencari ke seluruh ruangan dan menghubungi yang terakhir meminjam", s:4},{t:"Membuat dokumen pengganti diam-diam", s:3},{t:"Menyalahkan cleaning service", s:2},{t:"Berharap auditor tidak menanyakan dokumen itu", s:1}], ex:"Kehilangan dokumen negara wajib dilaporkan resmi dan ditelusuri; rekayasa pengganti diam-diam adalah pelanggaran."},
{id:"TKP-1707", q:"Anda menemukan selisih kas kecil yang tidak dapat dijelaskan bendahara. Sikap Anda ....", opts:[{t:"Melaporkan temuan secara resmi dan meminta audit internal untuk menelusurinya", s:5},{t:"Mendokumentasikan temuan dan berkonsultasi dengan atasan", s:4},{t:"Menegur bendahara secara pribadi", s:3},{t:"Membiarkan karena nilainya kecil", s:2},{t:"Ikut mengambil karena toh tidak ketahuan", s:1}], ex:"Selisih kas sekecil apa pun wajib ditelusuri resmi; pembiaran membuka pintu penyimpangan lebih besar."},
{id:"TKP-1708", q:"Seorang rekan sering datang terlambat dan meminta Anda menutupinya saat atasan bertanya. Sikap Anda ....", opts:[{t:"Menolak menutupi dan menyarankan rekan memperbaiki kedisiplinannya", s:5},{t:"Menolak berbohong tetapi tidak melaporkan rekan", s:4},{t:"Menutupi sekali ini saja", s:3},{t:"Rutin menutupi demi pertemanan", s:2},{t:"Ikut datang terlambat juga", s:1}], ex:"Menutupi ketidakdisiplinan rekan adalah kebohongan; menolak dengan saran perbaikan adalah sikap tepat."},
{id:"TKP-1709", q:"Perusahaan milik keluarga Anda mengikuti tender proyek di dinas tempat Anda bekerja. Sikap Anda ....", opts:[{t:"Menyatakan konflik kepentingan dan menarik diri dari seluruh proses tender tersebut", s:5},{t:"Meminta dipindahkan dari kepanitiaan tender", s:4},{t:"Tetap terlibat tetapi bersikap objektif", s:3},{t:"Membantu perusahaan keluarga diam-diam", s:2},{t:"Memastikan perusahaan keluarga menang", s:1}], ex:"Konflik kepentingan harus dihindari total dengan menarik diri, bukan sekadar klaim objektif."},
{id:"TKP-1710", q:"Atasan meminta Anda memanipulasi data laporan agar kinerja unit terlihat baik. Sikap Anda ....", opts:[{t:"Menolak dan menyampaikan data apa adanya, karena laporan palsu merugikan pengambilan keputusan", s:5},{t:"Mengusulkan menampilkan data asli disertai rencana perbaikan", s:4},{t:"Meminta perintah tertulis sebelum melaksanakan", s:3},{t:"Memanipulasi sesuai perintah", s:2},{t:"Memanipulasi dan menyembunyikannya", s:1}], ex:"Data kinerja yang dimanipulasi menyesatkan pimpinan; kejujuran data adalah dasar perbaikan yang sesungguhnya."},
{id:"TKP-1711", q:"Anda ditugaskan dalam tim gabungan dengan kepolisian untuk penertiban pasar. Ada perbedaan cara kerja antara kedua instansi. Sikap Anda ....", opts:[{t:"Berinisiatif menyelaraskan prosedur kerja bersama sejak awal agar operasi berjalan solid", s:5},{t:"Mengikuti arahan koordinator tim gabungan", s:4},{t:"Bekerja sendiri sesuai kebiasaan instansi masing-masing", s:3},{t:"Menunggu pihak kepolisian yang mengatur", s:2},{t:"Menarik diri dari tim gabungan", s:1}], ex:"Kerja sama lintas instansi membutuhkan penyelarasan prosedur aktif, bukan jalan sendiri-sendiri."},
{id:"TKP-1712", q:"Program normalisasi sungai melibatkan tiga kecamatan dengan kepentingan berbeda. Anda koordinator. Sikap Anda ....", opts:[{t:"Menyusun rencana bersama yang mengakomodasi kepentingan tiap kecamatan secara proporsional", s:5},{t:"Mengadakan rapat koordinasi rutin untuk menyelaraskan progres", s:4},{t:"Memprioritaskan kecamatan yang paling vokal", s:3},{t:"Menyerahkan keputusan ke dinas provinsi", s:2},{t:"Membiarkan tiap kecamatan bekerja sendiri", s:1}], ex:"Koordinasi lintas wilayah menuntut rencana bersama yang adil, bukan dominasi pihak yang paling vokal."},
{id:"TKP-1713", q:"Program kerja Anda membutuhkan data dari dinas lain yang lambat merespons. Sikap Anda ....", opts:[{t:"Mendatangi langsung, membangun komunikasi baik, dan menawarkan bantuan agar data bisa dibagikan", s:5},{t:"Mengirim surat resmi dengan tenggat yang jelas", s:4},{t:"Menunggu sampai dinas tersebut merespons", s:3},{t:"Melaporkan ke pimpinan sebagai hambatan", s:2},{t:"Membuat data perkiraan sendiri", s:1}], ex:"Hambatan birokrasi diatasi dengan komunikasi proaktif dan tawaran bantuan, bukan menunggu atau merekayasa data."},
{id:"TKP-1714", q:"Seorang CPNS baru di unit Anda kesulitan beradaptasi dengan sistem kerja dan terlihat tertekan. Anda senior. Sikap Anda ....", opts:[{t:"Menjadi mentor, membimbing bertahap, dan memberi ruang bertanya tanpa menghakimi", s:5},{t:"Menawarkan bantuan dan membagikan panduan kerja", s:4},{t:"Membiarkan ia belajar sendiri seperti dulu Anda", s:3},{t:"Melaporkan ke atasan bahwa ia lambat", s:2},{t:"Memanfaatkannya untuk pekerjaan yang tidak disukai", s:1}], ex:"Membimbing junior adalah investasi tim; mentoring yang sabar mempercepat adaptasi dan membangun loyalitas."},
{id:"TKP-1715", q:"Seorang anggota tim sangat pasif dan tidak berkontribusi dalam proyek bersama. Anda ketua tim. Sikap Anda ....", opts:[{t:"Berdiskusi empat mata untuk memahami kendalanya, lalu memberi peran yang sesuai kemampuannya", s:5},{t:"Membagi tugas yang jelas dengan tenggat untuk tiap anggota", s:4},{t:"Membiarkan dan mengerjakan bagiannya sendiri", s:3},{t:"Mengeluarkannya dari tim", s:2},{t:"Mempermalukannya di depan tim", s:1}], ex:"Kepemimpinan tim menyelesaikan masalah anggota dengan dialog dan penempatan peran yang tepat."},
{id:"TKP-1716", q:"Setelah konflik antar anggota, kekompakan tim Anda menurun drastis. Sikap Anda ....", opts:[{t:"Memfasilitasi rekonsiliasi terbuka dan membangun kembali kepercayaan melalui kegiatan bersama", s:5},{t:"Mengajak bicara pihak-pihak yang berkonflik satu per satu", s:4},{t:"Membiarkan waktu menyembuhkan", s:3},{t:"Memihak salah satu pihak", s:2},{t:"Meminta pimpinan membubarkan tim", s:1}], ex:"Konflik tim diselesaikan dengan fasilitasi aktif, bukan didiamkan atau diambil alih pihak luar."},
{id:"TKP-1717", q:"Seorang pegawai senior akan pensiun dan banyak pengetahuannya belum terdokumentasi. Anda atasannya. Tindakan Anda ....", opts:[{t:"Mengatur program alih pengetahuan terstruktur sebelum ia pensiun, termasuk pendampingan penggantinya", s:5},{t:"Meminta senior menyusun panduan tertulis selama masa transisi", s:4},{t:"Berharap pengganti bisa belajar sendiri", s:3},{t:"Membiarkan pengetahuan hilang bersama pensiunnya", s:2},{t:"Meminta senior tetap bekerja tanpa status jelas", s:1}], ex:"Alih pengetahuan terstruktur mencegah hilangnya institutional knowledge saat pegawai kunci pensiun."},
{id:"TKP-1718", q:"Kepala desa mitra program Anda sulit dihubungi sehingga koordinasi tersendat. Sikap Anda ....", opts:[{t:"Mendatangi langsung dengan jadwal yang disepakati dan membangun hubungan baik", s:5},{t:"Menghubungi melalui perangkat desa atau jalur alternatif", s:4},{t:"Mengirim surat dan menunggu balasan", s:3},{t:"Melaporkan sebagai tidak kooperatif", s:2},{t:"Menjalankan program tanpa melibatkan desa", s:1}], ex:"Kemitraan dengan pemerintah desa dibangun dengan pendekatan langsung dan pengertian, bukan laporan negatif."},
{id:"TKP-1719", q:"Unit Anda bekerja sama dengan peneliti universitas, tetapi jadwal dan metode kerja berbeda jauh. Sikap Anda ....", opts:[{t:"Menyepakati pembagian peran dan jadwal bersama yang realistis sejak awal kerja sama", s:5},{t:"Menyesuaikan ritme kerja dengan kalender akademik mitra", s:4},{t:"Memaksa mitra mengikuti jadwal dinas", s:3},{t:"Membiarkan kerja sama berjalan tanpa kesepakatan", s:2},{t:"Membatalkan kerja sama", s:1}], ex:"Kemitraan riset berhasil dengan kesepakatan peran dan jadwal yang disusun bersama sejak awal."},
{id:"TKP-1720", q:"Unit Anda ingin bermitra dengan LSM untuk program sosial, tetapi ada keraguan soal kredibilitas LSM tersebut. Sikap Anda ....", opts:[{t:"Melakukan uji tuntas rekam jejak LSM, menyusun MoU yang jelas, dan memonitor pelaksanaannya", s:5},{t:"Memulai dengan proyek percontohan skala kecil", s:4},{t:"Menolak bekerja sama karena ragu", s:3},{t:"Bekerja sama tanpa verifikasi", s:2},{t:"Memanfaatkan LSM untuk pencitraan semata", s:1}], ex:"Kemitraan dengan pihak ketiga harus didahului uji tuntas dan perjanjian jelas, bukan prasangka atau kecerobohan."},
{id:"TKP-1721", q:"Seorang rekan mengambil kredit atas ide Anda dalam presentasi ke pimpinan. Sikap Anda ....", opts:[{t:"Menyampaikan klarifikasi secara profesional dengan bukti, tanpa menjatuhkan rekan di depan umum", s:5},{t:"Berdiskusi langsung dengan rekan tersebut secara dewasa", s:4},{t:"Diam demi menjaga hubungan", s:3},{t:"Menyebarluaskan bahwa ide itu milik Anda", s:2},{t:"Membalas dengan mencuri ide rekan lain", s:1}], ex:"Hak atas ide diperjuangkan secara profesional dan bermartabat, bukan dengan diam atau balas dendam."},
{id:"TKP-1722", q:"Ketua tim Anda micromanaging; setiap detail harus lapor dan ia sering mengubah keputusan sepihak. Sikap Anda ....", opts:[{t:"Menyampaikan masukan secara konstruktif dan mengusulkan pembagian wewenang yang jelas", s:5},{t:"Berdiskusi empat mata tentang efektivitas cara kerjanya", s:4},{t:"Mengikuti saja apa pun keputusannya", s:3},{t:"Melawan setiap keputusannya", s:2},{t:"Menghasut anggota lain untuk menolaknya", s:1}], ex:"Masalah gaya kepemimpinan diselesaikan dengan masukan konstruktif, bukan perlawanan atau kepatuhan buta."},
{id:"TKP-1723", q:"Tim Anda bekerja jarak jauh via daring dan koordinasi sering miskomunikasi. Sikap Anda ....", opts:[{t:"Mengusulkan aturan komunikasi yang jelas: jadwal check-in, kanal resmi, dan dokumentasi keputusan", s:5},{t:"Berinisiatif merangkum setiap diskusi penting secara tertulis", s:4},{t:"Mengikuti alur seadanya", s:3},{t:"Menyalahkan rekan yang tidak responsif", s:2},{t:"Menarik diri dari diskusi daring", s:1}], ex:"Kerja jarak jauh butuh disiplin komunikasi yang disepakati bersama, bukan sekadar aplikasi."},
{id:"TKP-1724", q:"Anda petugas shift di layanan 24 jam. Rekan pengganti shift sering terlambat datang. Sikap Anda ....", opts:[{t:"Berdiskusi baik-baik dengannya dan jika berlanjut melaporkannya sesuai mekanisme", s:5},{t:"Menyepakati sistem serah terima yang terdokumentasi", s:4},{t:"Tetap menunggu tanpa protes", s:3},{t:"Pulang tepat waktu dan membiarkan layanan kosong", s:2},{t:"Memalsukan catatan serah terima", s:1}], ex:"Kedisiplinan shift menyangkut pelayanan publik; diselesaikan lewat dialog lalu mekanisme resmi."},
{id:"TKP-1725", q:"Anda tergabung dalam tim inspeksi gabungan ke lapangan. Salah satu anggota tidak paham tugasnya. Sikap Anda ....", opts:[{t:"Menjelaskan tugasnya dengan sabar dan mendampinginya selama inspeksi", s:5},{t:"Membagi ulang tugas sesuai kemampuan masing-masing", s:4},{t:"Mengerjakan tugasnya sekalian", s:3},{t:"Melaporkan ke koordinator sebagai tidak kompeten", s:2},{t:"Membiarkannya dan fokus pada tugas sendiri", s:1}], ex:"Soliditas tim inspeksi dibangun dengan saling membantu, bukan saling menjatuhkan."},
{id:"TKP-1726", q:"Anda ditugaskan dalam tim tanggap bencana. Di lokasi, warga panik dan tim belum solid. Sikap Anda ....", opts:[{t:"Mengambil inisiatif menenangkan warga sambil mengoordinasikan pembagian tugas tim", s:5},{t:"Fokus pada tugas yang dikuasai sambil membantu yang lain", s:4},{t:"Menunggu komando ketua tim", s:3},{t:"Panik mengikuti warga", s:2},{t:"Meninggalkan lokasi karena tidak siap", s:1}], ex:"Dalam kedaruratan, inisiatif menenangkan dan mengoordinasikan adalah wujud kepemimpinan lapangan."},
{id:"TKP-1727", q:"Anda menjadi panitia perayaan 17 Agustus tingkat kecamatan dengan anggaran minim. Sikap Anda ....", opts:[{t:"Mengoptimalkan swadaya masyarakat dan sponsor lokal dengan proposal yang transparan", s:5},{t:"Menyusun acara sederhana namun bermakna sesuai anggaran", s:4},{t:"Meminta tambahan anggaran ke kabupaten", s:3},{t:"Membatalkan perayaan", s:2},{t:"Memungut iuran paksa dari warga", s:1}], ex:"Keterbatasan anggaran diatasi dengan kreativitas dan partisipasi, bukan pungutan paksa."},
{id:"TKP-1728", q:"Seorang rekan satu tim gemar bergosip tentang kehidupan pribadi anggota lain. Sikap Anda ....", opts:[{t:"Menegurnya secara pribadi dan tidak ikut menyebarkan gosip", s:5},{t:"Mengalihkan pembicaraan ke topik pekerjaan setiap kali ia bergosip", s:4},{t:"Mendengarkan tetapi tidak menanggapi", s:3},{t:"Ikut bergosip agar diterima", s:2},{t:"Menyebarkan gosip balasan tentangnya", s:1}], ex:"Gosip merusak kepercayaan tim; menegur dan tidak ikut serta adalah sikap profesional."},
{id:"TKP-1729", q:"Dua unit berebut pemakaian kendaraan dinas pada hari yang sama untuk kegiatan penting. Anda pengelola aset. Sikap Anda ....", opts:[{t:"Menyusun jadwal pakai bersama yang adil berdasarkan urgensi, dan mengupayakan sewa tambahan jika perlu", s:5},{t:"Memediasi kedua unit untuk berbagi waktu penggunaan", s:4},{t:"Memberi ke unit yang meminta lebih dulu", s:3},{t:"Memberi ke unit yang dipimpin atasan lebih tinggi", s:2},{t:"Membiarkan keduanya berebut sendiri", s:1}], ex:"Pengelolaan aset bersama menuntut penjadwalan adil berbasis urgensi, bukan senioritas."},
{id:"TKP-1730", q:"Anda diminta memasangkan pegawai senior dengan junior dalam program mentoring, tetapi senior enggan. Sikap Anda ....", opts:[{t:"Menjelaskan manfaat mentoring bagi keduanya dan memfasilitasi pertemuan awal yang santai", s:5},{t:"Memberi penghargaan atau pengakuan bagi mentor aktif", s:4},{t:"Memaksa senior menjalankan program", s:3},{t:"Membatalkan program mentoring", s:2},{t:"Membiarkan berjalan formalitas saja", s:1}], ex:"Mentoring berhasil bila senior memahami manfaatnya; fasilitasi dan apresiasi lebih efektif dari paksaan."},
{id:"TKP-1731", q:"Seorang rekan selalu berdalih bukan tugasku setiap diminta membantu pekerjaan tim. Sikap Anda ....", opts:[{t:"Berdiskusi tentang semangat gotong royong tim dan memberi contoh dengan membantu duluan", s:5},{t:"Mengusulkan pembagian tugas yang lebih jelas agar tidak ada celah", s:4},{t:"Membiarkan dan tidak melibatkannya", s:3},{t:"Melaporkannya sebagai tidak kooperatif", s:2},{t:"Membalas dengan menolak membantunya juga", s:1}], ex:"Sikap individualis diubah dengan dialog dan keteladanan, bukan pengucilan atau balasan."},
{id:"TKP-1732", q:"Tim Anda ingin mengadakan kegiatan kebersamaan tetapi anggaran kantor tidak boleh dipakai. Sikap Anda ....", opts:[{t:"Mengusulkan iuran sukarela yang transparan dengan nominal wajar", s:5},{t:"Mengadakan kegiatan sederhana tanpa biaya besar", s:4},{t:"Memaksa semua anggota iuran", s:3},{t:"Menggunakan anggaran kantor diam-diam", s:2},{t:"Membatalkan dan menyalahkan aturan", s:1}], ex:"Kebersamaan tim bisa dibangun tanpa melanggar aturan anggaran; iuran sukarela yang transparan adalah solusinya."},
{id:"TKP-1733", q:"Rotasi tugas menempatkan Anda pada pekerjaan yang tidak disukai. Sikap Anda ....", opts:[{t:"Menerima dengan profesional dan berusaha menguasainya sebagai pengembangan diri", s:5},{t:"Mempelajari tugas baru dengan bertanya kepada yang berpengalaman", s:4},{t:"Mengerjakan seadanya", s:3},{t:"Memprotes rotasi ke atasan", s:2},{t:"Menolak rotasi tersebut", s:1}], ex:"Rotasi adalah bagian pengembangan ASN; menerimanya dengan profesional menunjukkan kedewasaan."},
{id:"TKP-1734", q:"Seorang anggota tim sedang berduka karena musibah keluarga di tengah tenggat proyek. Sikap Anda ....", opts:[{t:"Memberi izin berduka dengan empati dan mengatur ulang pembagian tugas tim untuk menutupinya", s:5},{t:"Menawarkan bantuan dan fleksibilitas jadwal", s:4},{t:"Meminta ia tetap menyelesaikan tugasnya dulu", s:3},{t:"Menganggap itu urusan pribadi", s:2},{t:"Mengeluarkannya dari proyek", s:1}], ex:"Empati pada musibah rekan diwujudkan dengan kelonggaran nyata dan dukungan tim."},
{id:"TKP-1735", q:"Anda perlu memberi umpan balik atas pekerjaan rekan yang hasilnya kurang baik. Sikap Anda ....", opts:[{t:"Menyampaikan secara empat mata dengan data, fokus pada perbaikan, dan mengapresiasi usahanya", s:5},{t:"Memberi masukan tertulis yang konstruktif", s:4},{t:"Menyampaikan di depan tim agar jadi contoh", s:3},{t:"Tidak memberi tahu dan memperbaikinya diam-diam", s:2},{t:"Mengkritik dengan kasar agar jera", s:1}], ex:"Umpan balik efektif bersifat privat, berbasis data, dan berorientasi solusi."},
{id:"TKP-1736", q:"Dalam rapat terjadi perbedaan pendapat yang tajam antara Anda dan rekan soal prioritas program. Sikap Anda ....", opts:[{t:"Menyampaikan argumen berbasis data dengan tenang dan mencari titik temu yang terbaik untuk organisasi", s:5},{t:"Mengusulkan uji coba kecil untuk membuktikan pendekatan masing-masing", s:4},{t:"Bersikeras mempertahankan pendapat", s:3},{t:"Menyerah agar rapat cepat selesai", s:2},{t:"Membawa konflik ke luar rapat", s:1}], ex:"Perbedaan pendapat profesional diselesaikan dengan data dan pencarian solusi bersama, bukan emosi."},
{id:"TKP-1737", q:"Pembagian tugas kelompok tidak adil dan Anda mendapat porsi terbanyak. Sikap Anda ....", opts:[{t:"Menyampaikan keberatan secara terbuka dan mengusulkan pembagian ulang yang proporsional", s:5},{t:"Berdiskusi dengan ketua kelompok tentang beban masing-masing", s:4},{t:"Mengerjakan semuanya tanpa protes", s:3},{t:"Mengerjakan asal-asalan sebagai protes", s:2},{t:"Keluar dari kelompok", s:1}], ex:"Ketidakadilan beban kerja diselesaikan lewat komunikasi terbuka, bukan kepasrahan atau sabotase."},
{id:"TKP-1738", q:"Seorang rekan senior sulit menerima ide baru yang Anda usulkan karena merasa pengalamannya lebih. Sikap Anda ....", opts:[{t:"Mempresentasikan ide dengan data dan menghargai pengalamannya, mengajak menguji ide bersama", s:5},{t:"Meminta masukan senior untuk menyempurnakan ide", s:4},{t:"Menyerah dan mengikuti cara lama", s:3},{t:"Memaksakan ide karena merasa lebih modern", s:2},{t:"Menyindir senior di depan rekan lain", s:1}], ex:"Ide baru diterima bila disampaikan dengan menghargai pengalaman; kolaborasi mengalahkan konfrontasi."},
{id:"TKP-1739", q:"Unit lain menolak berbagi informasi dengan alasan bukan urusanmu. Padahal data itu penting untuk program Anda. Sikap Anda ....", opts:[{t:"Mengajukan permintaan resmi dengan dasar kebutuhan program dan menawarkan timbal balik yang saling menguntungkan", s:5},{t:"Berdiskusi dengan pimpinan unit tersebut untuk mencari jalan keluar", s:4},{t:"Mencari data dari sumber lain", s:3},{t:"Melaporkan sebagai hambatan ke pimpinan", s:2},{t:"Membocorkan data mereka sebagai balasan", s:1}], ex:"Ego sektoral diatasi dengan permintaan resmi yang jelas dasarnya dan tawaran kerja sama timbal balik."},
{id:"TKP-1740", q:"Unit Anda diminta membantu unit lain yang kekurangan personel saat ada kegiatan besar. Beban kerja Anda sendiri sudah padat. Sikap Anda ....", opts:[{t:"Bersedia membantu dengan mengatur prioritas dan membagi waktu secara proporsional", s:5},{t:"Menawarkan bantuan untuk bagian yang paling kritis", s:4},{t:"Menolak karena beban sendiri sudah padat", s:3},{t:"Membantu tetapi menggerutu", s:2},{t:"Berpura-pura sibuk agar tidak diminta", s:1}], ex:"Solidaritas antar unit adalah nilai ASN; bantuan diberikan dengan pengaturan prioritas yang bijak."},
{id:"TKP-1741", q:"Warga lintas agama di kampung Anda mengadakan gotong royong membersihkan lingkungan. Seorang warga menolak ikut karena pesertanya beda keyakinan. Anda tokoh pemuda. Sikap Anda ....", opts:[{t:"Mengajaknya dengan menjelaskan bahwa gotong royong soal kebersihan bersama, bukan soal keyakinan", s:5},{t:"Memberi contoh dengan ikut aktif dalam kegiatan tersebut", s:4},{t:"Membiarkan keputusannya", s:3},{t:"Mengkritiknya di depan warga lain", s:2},{t:"Ikut menolak agar kompak", s:1}], ex:"Toleransi diwujudkan dalam aksi bersama; gotong royong lintas iman memperkuat persatuan."},
{id:"TKP-1742", q:"Jadwal piket dinas bentrok dengan waktu ibadah seorang rekan yang berbeda agama dengan Anda. Sikap Anda ....", opts:[{t:"Berinisiatif bertukar jadwal piket dengannya secara sukarela", s:5},{t:"Mengusulkan penyesuaian jadwal ke atasan", s:4},{t:"Meminta rekan menyesuaikan ibadahnya", s:3},{t:"Membiarkan ia melanggar jadwal piket", s:2},{t:"Melaporkan sebagai indisipliner", s:1}], ex:"Menghormati ibadah rekan beda agama dengan bertukar jadwal adalah wujud toleransi aktif."},
{id:"TKP-1743", q:"Proyek pembangunan kantor akan melewati tanah adat yang disakralkan masyarakat setempat. Anda anggota tim proyek. Sikap Anda ....", opts:[{t:"Mengusulkan dialog dengan pemuka adat dan penyesuaian desain agar situs sakral tidak terganggu", s:5},{t:"Melibatkan tokoh adat dalam perencanaan sejak awal", s:4},{t:"Tetap membangun sesuai rencana awal", s:3},{t:"Menunggu protes warga baru bertindak", s:2},{t:"Mengabaikan nilai sakral demi efisiensi", s:1}], ex:"Pembangunan harus menghormati nilai adat; dialog dan penyesuaian desain mencegah konflik."},
{id:"TKP-1744", q:"Seorang warga lanjut usia hanya fasih berbahasa daerah dan tidak memahami penjelasan prosedur Anda. Sikap Anda ....", opts:[{t:"Berusaha menjelaskan dengan bahasa daerah sebisanya atau meminta bantuan rekan yang fasih", s:5},{t:"Menggunakan bahasa sederhana disertai isyarat dan contoh konkret", s:4},{t:"Meminta warga membawa pendamping yang bisa bahasa Indonesia", s:3},{t:"Mengulang penjelasan dengan bahasa Indonesia yang lebih keras", s:2},{t:"Menyuruh warga pulang dan kembali dengan penerjemah", s:1}], ex:"Pelayanan inklusif menjangkau warga dengan keterbatasan bahasa; inisiatif mencari jalan komunikasi adalah kewajiban."},
{id:"TKP-1745", q:"Dinas Anda diminta mendukung festival budaya daerah yang melibatkan banyak komunitas adat. Sikap Anda ....", opts:[{t:"Berpartisipasi aktif dan membantu koordinasi agar festival berjalan sukses dan inklusif", s:5},{t:"Mendukung sesuai tugas yang diberikan", s:4},{t:"Hadir sekadar formalitas", s:3},{t:"Menolak terlibat karena bukan budaya Anda", s:2},{t:"Mengkritik anggaran festival", s:1}], ex:"Aparatur mendukung pelestarian budaya daerah sebagai bagian dari jati diri bangsa."},
{id:"TKP-1746", q:"Anda harus berkoordinasi dengan tokoh adat yang tata kramanya sangat formal dan berbeda. Sikap Anda ....", opts:[{t:"Mempelajari dan menghormati tata krama setempat dalam setiap interaksi", s:5},{t:"Bersikap sopan dan mengikuti arahan protokol setempat", s:4},{t:"Bersikap biasa saja seperti dengan rekan kantor", s:3},{t:"Menganggap tata krama adat sebagai penghambat", s:2},{t:"Menolak berkoordinasi dengan tokoh adat", s:1}], ex:"Menghormati tata krama adat adalah kunci keberhasilan koordinasi dengan masyarakat tradisional."},
{id:"TKP-1747", q:"Di kantor yang karyawannya beragam, ada rekan yang tersinggung oleh candaan Anda yang menyentuh keyakinannya. Sikap Anda ....", opts:[{t:"Segera meminta maaf dengan tulus dan berkomitmen menjaga lisan ke depannya", s:5},{t:"Menjelaskan tidak bermaksud menyinggung dan meminta maaf", s:4},{t:"Menganggapnya terlalu sensitif", s:3},{t:"Membela diri bahwa itu hanya candaan", s:2},{t:"Mengulangi candaan serupa", s:1}], ex:"Permintaan maaf yang tulus dan komitmen berubah adalah respons tepat atas ketersinggungan."},
{id:"TKP-1748", q:"Acara kantor menyediakan hidangan yang tidak bisa dimakan sebagian rekan karena keyakinan. Anda panitia. Sikap Anda ....", opts:[{t:"Menyediakan pilihan menu yang mengakomodasi semua keyakinan sejak perencanaan", s:5},{t:"Menanyakan kebutuhan khusus rekan sebelum memesan hidangan", s:4},{t:"Meminta rekan yang berkeberatan membawa bekal sendiri", s:3},{t:"Membiarkan apa adanya", s:2},{t:"Menganggap rekan tersebut merepotkan", s:1}], ex:"Perencanaan acara yang inklusif memperhatikan kebutuhan semua sejak awal."},
{id:"TKP-1749", q:"Rekan Anda sedang berpuasa menurut keyakinannya dan terlihat lemas saat rapat panjang. Sikap Anda ....", opts:[{t:"Menawarkan istirahat sejenak dan menyesuaikan tempo rapat dengan pengertian", s:5},{t:"Menanyakan kondisinya dan menawarkan bantuan", s:4},{t:"Melanjutkan rapat seperti biasa", s:3},{t:"Menyindirnya kurang profesional", s:2},{t:"Memintanya keluar dari rapat", s:1}], ex:"Pengertian terhadap rekan yang beribadah puasa menunjukkan empati dan solidaritas."},
{id:"TKP-1750", q:"Seorang rekan meminta cuti untuk upacara adat besar di kampungnya yang tidak dikenal di kalender resmi. Anda atasannya. Sikap Anda ....", opts:[{t:"Memberi izin cuti dengan memahami nilai penting upacara adat baginya", s:5},{t:"Menyetujui cuti sesuai ketentuan yang berlaku", s:4},{t:"Memberi izin tetapi memotong tunjangan", s:3},{t:"Menolak karena bukan hari libur resmi", s:2},{t:"Menolak dan memberi sanksi", s:1}], ex:"Menghormati upacara adat sama pentingnya dengan hari besar keagamaan resmi."},
{id:"TKP-1751", q:"Dua keluarga di desa bersengketa warisan tanah adat dan meminta Anda sebagai perangkat desa memediasi. Sikap Anda ....", opts:[{t:"Memfasilitasi mediasi dengan melibatkan pemuka adat dan memegang teguh netralitas", s:5},{t:"Mendengarkan kedua belah pihak secara adil sebelum memberi saran", s:4},{t:"Memihak keluarga yang lebih dulu melapor", s:3},{t:"Menolak memediasi karena rumit", s:2},{t:"Memutuskan sepihak berdasarkan kedekatan", s:1}], ex:"Mediasi sengketa adat menuntut netralitas dan pelibatan pemuka adat yang dihormati."},
{id:"TKP-1752", q:"Sanggar tari tradisional di daerah Anda sepi peminat karena anak muda lebih tertarik budaya populer. Anda pejabat kebudayaan. Tindakan Anda ....", opts:[{t:"Menggandeng sekolah dan komunitas untuk program pelestarian yang menarik bagi generasi muda", s:5},{t:"Memberi dukungan dana dan fasilitas untuk sanggar", s:4},{t:"Membiarkan sesuai mekanisme pasar", s:3},{t:"Menutup sanggar yang sepi", s:2},{t:"Menganggap budaya tradisional ketinggalan zaman", s:1}], ex:"Pelestarian budaya butuh strategi aktif menjangkau generasi muda, bukan pembiaran."},
{id:"TKP-1753", q:"Sejumlah wisatawan berperilaku tidak sopan di situs sakral, dan warga setempat marah. Anda pengelola destinasi. Tindakan Anda ....", opts:[{t:"Menegur wisatawan dengan sopan, menjelaskan tata krama setempat, dan memperkuat rambu serta pemandu", s:5},{t:"Memasang aturan tata krama yang jelas di pintu masuk", s:4},{t:"Membiarkan karena wisatawan adalah tamu", s:3},{t:"Mengusir wisatawan dengan kasar", s:2},{t:"Menutup situs untuk umum", s:1}], ex:"Edukasi tata krama yang tegas namun sopan melindungi kesakralan situs tanpa merusak pariwisata."},
{id:"TKP-1754", q:"Rekan baru dari Papua kesulitan memahami logat Anda dan sering salah paham instruksi. Sikap Anda ....", opts:[{t:"Berbicara lebih pelan dan jelas, mengonfirmasi pemahamannya, dan membangun kedekatan personal", s:5},{t:"Menulis instruksi penting secara tertulis", s:4},{t:"Menganggapnya kurang cepat tanggap", s:3},{t:"Meminta ia beradaptasi sendiri", s:2},{t:"Menghindarinya dalam penugasan", s:1}], ex:"Hambatan komunikasi antardaerah diatasi dengan kesabaran dan penyesuaian cara berkomunikasi."},
{id:"TKP-1755", q:"Seorang rekan melontarkan candaan stereotip tentang suku rekan lain di ruang kerja. Sikap Anda ....", opts:[{t:"Menegur dengan tegas bahwa stereotip suku tidak bisa ditoleransi di lingkungan kerja", s:5},{t:"Mengingatkan bahwa candaan seperti itu melukai dan merusak kebersamaan", s:4},{t:"Tertawa kecil agar tidak canggung", s:3},{t:"Ikut menambahi candaan", s:2},{t:"Diam saja bukan urusan Anda", s:1}], ex:"Stereotip suku di tempat kerja harus ditegur tegas; pembiaran sama dengan pembenaran."},
{id:"TKP-1756", q:"Dekorasi kantor menjelang hari besar keagamaan tertentu membuat rekan berbeda keyakinan merasa tidak nyaman. Anda bagian umum. Sikap Anda ....", opts:[{t:"Membuat dekorasi yang netral dan merayakan kebersamaan, atau memberi ruang ekspresi seimbang bagi semua", s:5},{t:"Berdiskusi dengan semua pihak untuk dekorasi yang disepakati", s:4},{t:"Tetap memasang dekorasi satu keyakinan saja", s:3},{t:"Menghapus semua dekorasi", s:2},{t:"Mengabaikan keberatan rekan", s:1}], ex:"Ruang kerja bersama harus nyaman bagi semua; dekorasi inklusif atau seimbang adalah solusinya."},
{id:"TKP-1757", q:"Ruang ibadah kecil di kantor diperebutkan jadwalnya oleh pemeluk agama berbeda. Sikap Anda ....", opts:[{t:"Menyusun jadwal pakai bersama yang adil dan disepakati semua pihak", s:5},{t:"Memfasilitasi musyawarah penggunaan ruang", s:4},{t:"Memberi prioritas pada mayoritas", s:3},{t:"Menutup ruang ibadah", s:2},{t:"Membiarkan siapa cepat dia dapat", s:1}], ex:"Fasilitas bersama dikelola dengan jadwal adil hasil musyawarah, bukan dominasi mayoritas."},
{id:"TKP-1758", q:"Seorang rekan mengenakan pakaian keagamaan yang mencolok dan ada yang mengomentari negatif. Sikap Anda ....", opts:[{t:"Membela hak rekan berpakaian sesuai keyakinannya dan menegur yang mengomentari", s:5},{t:"Menyatakan bahwa keberagaman pakaian adalah hal yang dilindungi", s:4},{t:"Diam agar tidak terlibat", s:3},{t:"Ikut mengomentari", s:2},{t:"Menyarankan rekan berpakaian lebih netral", s:1}], ex:"Kebebasan berkeyakinan termasuk berpakaian; komentar negatif harus ditegur, bukan dinormalisasi."},
{id:"TKP-1759", q:"Pasangan beda agama meminta bantuan pengurusan dokumen kependudukan dan mendapat penolakan halus dari petugas lain. Anda mengetahuinya. Sikap Anda ....", opts:[{t:"Membantu pengurusan sesuai ketentuan hukum yang berlaku tanpa diskriminasi", s:5},{t:"Menegur petugas yang diskriminatif dan memastikan layanan diberikan", s:4},{t:"Menyarankan pasangan mengurus di tempat lain", s:3},{t:"Membiarkan penolakan tersebut", s:2},{t:"Ikut menolak dengan alasan norma", s:1}], ex:"Layanan administrasi tidak boleh diskriminatif; hukum mengatur, bukan prasangka pribadi petugas."},
{id:"TKP-1760", q:"Pasca pemilu, hubungan antar warga pendukung kubu berbeda di desa Anda memanas. Anda perangkat desa. Tindakan Anda ....", opts:[{t:"Menginisiasi rekonsiliasi melalui kegiatan bersama dan mengajak tokoh kedua kubu berdamai", s:5},{t:"Mengajak tokoh masyarakat menyerukan persatuan", s:4},{t:"Menunggu reda dengan sendirinya", s:3},{t:"Memihak kubu pemenang", s:2},{t:"Membiarkan konflik berkepanjangan", s:1}], ex:"Aparatur desa wajib aktif merajut kembali persatuan pasca kontestasi politik."},
{id:"TKP-1761", q:"Seorang siswa menolak mengikuti upacara bendera karena keyakinan keluarganya. Anda guru. Sikap Anda ....", opts:[{t:"Menghormati keyakinannya sambil memberi pemahaman tentang makna upacara, dan mencari solusi yang tidak memaksa", s:5},{t:"Berdiskusi dengan orang tua untuk pemahaman bersama", s:4},{t:"Memaksa mengikuti upacara", s:3},{t:"Menghukum siswa tersebut", s:2},{t:"Mengeluarkannya dari sekolah", s:1}], ex:"Nasionalisme ditanamkan dengan pemahaman, bukan paksaan; keyakinan siswa tetap dihormati."},
{id:"TKP-1762", q:"Desa Anda menampung pengungsi konflik sosial dari daerah lain dengan latar belakang berbeda. Sikap Anda sebagai perangkat desa ....", opts:[{t:"Mengkoordinasikan penerimaan yang manusiawi dan mengajak warga setempat menyambut dengan empati", s:5},{t:"Menyiapkan kebutuhan dasar pengungsi bersama relawan", s:4},{t:"Menerima seadanya tanpa persiapan", s:3},{t:"Menolak karena khawatir masalah", s:2},{t:"Mengusir pengungsi tersebut", s:1}], ex:"Kemanusiaan melampaui perbedaan latar; penerimaan pengungsi yang terkoordinasi adalah kewajiban moral."},
{id:"TKP-1763", q:"Kantor Anda merencanakan perayaan hari besar keagamaan. Sebagian pegawai berbeda keyakinan merasa tersisih. Sikap Anda ....", opts:[{t:"Mengusulkan perayaan kebersamaan yang melibatkan semua, atau memberi ruang perayaan masing-masing secara adil", s:5},{t:"Mengajak semua pegawai terlibat dalam kepanitiaan bersama", s:4},{t:"Tetap merayakan satu keyakinan saja", s:3},{t:"Membatalkan semua perayaan", s:2},{t:"Mengabaikan yang merasa tersisih", s:1}], ex:"Kebersamaan dirayakan inklusif; tidak ada pegawai yang boleh merasa tersisih karena keyakinan."},
{id:"TKP-1764", q:"Anda dimutasi ke daerah dengan adat istiadat yang sangat berbeda. Sikap Anda ....", opts:[{t:"Mempelajari adat setempat dengan rendah hati dan beradaptasi tanpa meninggalkan jati diri", s:5},{t:"Bertanya dan bergaul dengan warga lokal untuk memahami kebiasaan", s:4},{t:"Menjalani dinas apa adanya", s:3},{t:"Mengeluhkan penempatan ke atasan", s:2},{t:"Menolak beradaptasi dengan alasan prinsip", s:1}], ex:"Mutasi adalah amanah; adaptasi budaya dengan rendah hati mempercepat penerimaan dan efektivitas kerja."},
{id:"TKP-1765", q:"Seorang sesepuh desa menegur cara kerja program Anda yang dinilai tidak sopan menurut adat. Sikap Anda ....", opts:[{t:"Menerima teguran dengan lapang dada, meminta maaf, dan menyesuaikan pendekatan", s:5},{t:"Berdiskusi untuk memahami tata krama yang diharapkan", s:4},{t:"Menjelaskan bahwa program sudah sesuai prosedur", s:3},{t:"Mengabaikan teguran orang tua", s:2},{t:"Melawan dan mempermalukannya", s:1}], ex:"Teguran sesepuh adalah kearifan lokal; menerima dan menyesuaikan menunjukkan kedewasaan aparatur."},
{id:"TKP-1766", q:"Dalam rapat, dialek daerah Anda sulit dipahami peserta dari daerah lain. Sikap Anda ....", opts:[{t:"Berusaha memakai bahasa Indonesia yang jelas demi kepentingan bersama", s:5},{t:"Mengulangi poin penting dengan bahasa yang mudah dipahami", s:4},{t:"Tetap memakai dialek karena itu identitas", s:3},{t:"Menyalahkan peserta yang tidak paham", s:2},{t:"Menolak berbicara dalam rapat", s:1}], ex:"Komunikasi efektif dalam forum beragam menuntut penyesuaian bahasa demi pemahaman bersama."},
{id:"TKP-1767", q:"Tradisi lokal memungut iuran warga untuk acara adat, tetapi ada warga miskin yang keberatan. Anda tokoh masyarakat. Sikap Anda ....", opts:[{t:"Mengusulkan iuran sukarela sesuai kemampuan agar tidak memberatkan yang miskin", s:5},{t:"Membebaskan warga tidak mampu dari iuran", s:4},{t:"Tetap memungut sama rata demi tradisi", s:3},{t:"Memaksa warga miskin tetap membayar", s:2},{t:"Menghapus tradisi tersebut", s:1}], ex:"Tradisi harus berjalan tanpa menindas yang lemah; iuran proporsional menjaga kebersamaan."},
{id:"TKP-1768", q:"Seorang warga minoritas kesulitan mengurus dokumen karena selalu dipersulit oknum. Ia mengadu kepada Anda. Sikap Anda ....", opts:[{t:"Membantu pengurusannya secara langsung dan melaporkan oknum yang mempersulit", s:5},{t:"Mendampingi warga sampai dokumennya selesai", s:4},{t:"Menyarankan mengurus di daerah lain", s:3},{t:"Membiarkan karena bukan wewenang Anda", s:2},{t:"Ikut mempersulit", s:1}], ex:"Diskriminasi dalam pelayanan adalah pelanggaran; membantu korban dan melaporkan pelaku adalah kewajiban."},
{id:"TKP-1769", q:"Dua kelompok pemuda desa terlibat tawuran akibat salah paham. Anda karang taruna senior. Tindakan Anda ....", opts:[{t:"Memediasi kedua kelompok, mencari akar masalah, dan mengajak kegiatan positif bersama", s:5},{t:"Melibatkan tokoh masyarakat dan aparat untuk perdamaian", s:4},{t:"Membiarkan sampai capek sendiri", s:3},{t:"Memihak kelompok yang dikenal", s:2},{t:"Ikut terlibat tawuran", s:1}], ex:"Konflik pemuda diselesaikan dengan mediasi dan pengalihan ke kegiatan positif."},
{id:"TKP-1770", q:"Bahasa daerah di wilayah Anda mulai ditinggalkan anak muda. Anda guru bahasa daerah. Tindakan Anda ....", opts:[{t:"Mengemas pembelajaran bahasa daerah dengan cara kreatif dan relevan bagi generasi muda", s:5},{t:"Mengadakan lomba dan festival bahasa daerah", s:4},{t:"Mengajar sesuai kurikulum seadanya", s:3},{t:"Menyerah karena zaman berubah", s:2},{t:"Memaksa murid memakai bahasa daerah", s:1}], ex:"Pelestarian bahasa daerah berhasil bila dikemas menarik dan relevan, bukan dengan paksaan."},
{id:"TKP-1771", q:"Komputer kantor Anda terkunci ransomware dengan pesan meminta tebusan. Tindakan pertama Anda ....", opts:[{t:"Segera memutuskan koneksi jaringan, melaporkan ke tim IT dan pimpinan, serta tidak membayar tebusan", s:5},{t:"Melaporkan ke atasan dan tim keamanan siber", s:4},{t:"Mencoba membuka kunci sendiri", s:3},{t:"Membayar tebusan agar cepat selesai", s:2},{t:"Menyembunyikan kejadian karena takut disalahkan", s:1}], ex:"Serangan siber ditangani dengan isolasi, pelaporan resmi, dan pantang membayar tebusan."},
{id:"TKP-1772", q:"Anda menerima email yang mengatasnamakan pimpinan meminta transfer dana mendesak. Sikap Anda ....", opts:[{t:"Memverifikasi langsung ke pimpinan melalui kanal resmi sebelum melakukan apa pun", s:5},{t:"Melaporkan email mencurigakan ke tim IT", s:4},{t:"Mengabaikan email tersebut", s:3},{t:"Meneruskan ke rekan untuk ditindaklanjuti", s:2},{t:"Langsung mentransfer karena dari pimpinan", s:1}], ex:"Phishing atasan palsu dicegah dengan verifikasi langsung lewat kanal resmi."},
{id:"TKP-1773", q:"Beredar video hasil AI yang memfitnah instansi Anda di media sosial dan mulai viral. Anda staf humas. Tindakan Anda ....", opts:[{t:"Menerbitkan klarifikasi resmi berbasis fakta, melaporkan konten ke platform, dan berkonsultasi dengan aparat jika perlu", s:5},{t:"Menyusun pernyataan resmi yang menenangkan publik", s:4},{t:"Membalas komentar netizen satu per satu", s:3},{t:"Mendiamkan dengan harapan reda sendiri", s:2},{t:"Membuat konten balasan yang menyerang penyebar", s:1}], ex:"Disinformasi dilawan dengan klarifikasi resmi yang tenang dan faktual, bukan emosi."},
{id:"TKP-1774", q:"Terjadi kebocoran data pribadi warga dari sistem instansi Anda. Sikap Anda ....", opts:[{t:"Melaporkan insiden sesuai prosedur, membantu notifikasi kepada warga terdampak, dan mendukung perbaikan keamanan", s:5},{t:"Berkonsultasi dengan pimpinan dan tim IT untuk langkah mitigasi", s:4},{t:"Menutupi agar tidak gaduh", s:3},{t:"Menyalahkan vendor sistem", s:2},{t:"Menghapus jejak keterlibatan Anda", s:1}], ex:"Kebocoran data wajib ditangani transparan dengan notifikasi dan perbaikan, bukan ditutupi."},
{id:"TKP-1775", q:"Seorang warga meminta data kependudukannya dikirim via WhatsApp pribadi Anda agar cepat. Sikap Anda ....", opts:[{t:"Menolak dan mengarahkan ke kanal layanan resmi yang aman dan terdokumentasi", s:5},{t:"Menjelaskan risiko pengiriman data pribadi via aplikasi pesan", s:4},{t:"Mengirimkan karena kasihan", s:3},{t:"Mengirimkan sebagian data saja", s:2},{t:"Mengirimkan dan meminta imbalan", s:1}], ex:"Data pribadi warga hanya disalurkan lewat kanal resmi; kemudahan tidak boleh mengorbankan keamanan."},
{id:"TKP-1776", q:"Anda terbiasa mengerjakan dokumen kantor di laptop pribadi karena lebih cepat. Sikap yang tepat ....", opts:[{t:"Menghentikan kebiasaan itu dan hanya mengolah data kantor di perangkat resmi yang aman", s:5},{t:"Memastikan laptop pribadi terlindungi dan tidak menyimpan data sensitif", s:4},{t:"Melanjutkan karena lebih efisien", s:3},{t:"Menyimpan salinan di cloud pribadi", s:2},{t:"Membagikan dokumen via email pribadi", s:1}], ex:"Data dinas di perangkat pribadi berisiko bocor; perangkat resmi adalah satu-satunya tempat yang benar."},
{id:"TKP-1777", q:"Tautan berbagi dokumen internal yang Anda buat ternyata tersebar ke pihak luar. Tindakan Anda ....", opts:[{t:"Segera mencabut akses tautan, mengganti dengan akses terbatas, dan melaporkan insiden", s:5},{t:"Memeriksa siapa saja yang mengakses dan mengamankan dokumen", s:4},{t:"Membiarkan karena dokumen tidak rahasia", s:3},{t:"Menghapus dokumen aslinya", s:2},{t:"Menyembunyikan kejadian", s:1}], ex:"Tautan yang bocor harus segera dicabut dan dievaluasi; kecepatan respons meminimalkan risiko."},
{id:"TKP-1778", q:"Dalam rapat video resmi, seorang peserta tidak sopan: kamera mati, disambi aktivitas lain. Anda moderator. Sikap Anda ....", opts:[{t:"Menegakkan tata tertib rapat dengan sopan dan mengingatkan etika kehadiran virtual", s:5},{t:"Menyampaikan aturan rapat daring di awal pertemuan", s:4},{t:"Membiarkan karena daring memang santai", s:3},{t:"Mengeluarkan peserta dari rapat", s:2},{t:"Menyindirnya di depan peserta lain", s:1}], ex:"Rapat virtual tetap forum resmi; etika ditegakkan dengan pengingat yang sopan."},
{id:"TKP-1779", q:"Beredar video deepfake yang menampilkan pejabat instansi Anda mengucapkan hal kontroversial. Anda staf. Sikap Anda ....", opts:[{t:"Tidak menyebarkan, melaporkan ke humas dan tim IT untuk verifikasi serta klarifikasi resmi", s:5},{t:"Mengingatkan rekan agar tidak ikut menyebarkan", s:4},{t:"Menonton saja untuk hiburan", s:3},{t:"Menyebarkan dengan caption lucu-lucuan", s:2},{t:"Menyebarkan sebagai fakta", s:1}], ex:"Deepfake pejabat harus diverifikasi dan diklarifikasi resmi; ikut menyebarkan memperparah fitnah."},
{id:"TKP-1780", q:"Seorang rekan meminta Anda meminjamkan tanda tangan digital Anda untuk mempercepat dokumen. Sikap Anda ....", opts:[{t:"Menolak tegas karena tanda tangan digital bersifat pribadi dan setara tanda tangan basah", s:5},{t:"Menjelaskan risiko hukum penyalahgunaan tanda tangan digital", s:4},{t:"Meminjamkan sekali ini saja", s:3},{t:"Meminjamkan karena rekan dekat", s:2},{t:"Memberi PIN sekalian agar praktis", s:1}], ex:"Tanda tangan digital tidak boleh dipinjamkan dalam kondisi apa pun; ia melekat pada pertanggungjawaban pribadi."},
{id:"TKP-1781", q:"Hoaks tentang program instansi Anda menyebar di grup WhatsApp warga. Anda admin grup resmi. Tindakan Anda ....", opts:[{t:"Mengunggah klarifikasi resmi dengan bahasa mudah dipahami dan mengajak warga cek fakta", s:5},{t:"Berkonsultasi dengan humas untuk materi bantahan", s:4},{t:"Menghapus pesan hoaks tanpa penjelasan", s:3},{t:"Membiarkan karena bukan grup resmi", s:2},{t:"Ikut meneruskan karena terlihat meyakinkan", s:1}], ex:"Hoaks dilawan dengan klarifikasi resmi yang mudah dipahami di kanal yang sama tempat ia menyebar."},
{id:"TKP-1782", q:"Sebagai admin media sosial instansi, Anda tergoda menanggapi komentar pedas netizen dengan emosi. Sikap Anda ....", opts:[{t:"Menahan diri, merespons dengan bahasa profesional, atau berkonsultasi dengan tim humas", s:5},{t:"Membalas dengan fakta secara tenang", s:4},{t:"Menghapus komentar pedas", s:3},{t:"Membalas dengan sindiran", s:2},{t:"Memblokir netizen tersebut", s:1}], ex:"Akun resmi adalah wajah institusi; respons profesional menjaga martabat instansi."},
{id:"TKP-1783", q:"Website instansi Anda diretas dan menampilkan konten tidak pantas. Anda pengelola. Tindakan Anda ....", opts:[{t:"Segera menonaktifkan sementara, melaporkan ke tim keamanan siber, dan memulihkan dari cadangan bersih", s:5},{t:"Berkonsultasi dengan penyedia hosting dan tim IT", s:4},{t:"Menghapus konten peretas manual", s:3},{t:"Membiarkan sampai jam kerja", s:2},{t:"Menyembunyikan dari pimpinan", s:1}], ex:"Peretasan situs ditangani cepat dengan isolasi dan pemulihan resmi, bukan ditutupi."},
{id:"TKP-1784", q:"Ditemukan calo yang memborong slot antrean online layanan Anda lalu menjualnya. Tindakan Anda ....", opts:[{t:"Memperketat verifikasi identitas pendaftar, membatalkan slot calo, dan melaporkan ke aparat", s:5},{t:"Mengevaluasi sistem antrean agar tidak bisa diborong", s:4},{t:"Membiarkan karena slot tetap terisi", s:3},{t:"Bekerja sama dengan calo", s:2},{t:"Menutup layanan online", s:1}], ex:"Calo antrean merugikan warga; sistem diperketat dan pelaku dilaporkan."},
{id:"TKP-1785", q:"Ada dugaan penipuan QRIS di loket pembayaran: dana masuk ke rekening pribadi oknum. Anda mengetahuinya. Sikap Anda ....", opts:[{t:"Melaporkan dugaan penipuan ke atasan dan inspektorat dengan bukti", s:5},{t:"Mengamankan bukti transaksi dan mencatat kronologi", s:4},{t:"Menegur oknum secara pribadi", s:3},{t:"Diam karena tidak ada bukti kuat", s:2},{t:"Ikut memanfaatkan celah tersebut", s:1}], ex:"Dugaan penipuan pembayaran wajib dilaporkan resmi dengan bukti; pembiaran adalah pembenaran."},
{id:"TKP-1786", q:"Memo internal yang bersifat rahasia bocor ke publik dan Anda tahu siapa penyebarnya. Sikap Anda ....", opts:[{t:"Melaporkan penyebar melalui jalur resmi sesuai aturan disiplin", s:5},{t:"Menasihati penyebar agar tidak mengulangi", s:4},{t:"Diam karena takut bermusuhan", s:3},{t:"Ikut menyebarkan karena isinya menarik", s:2},{t:"Memanfaatkan bocoran untuk kepentingan pribadi", s:1}], ex:"Kebocoran dokumen rahasia adalah pelanggaran disiplin; pelaporannya lewat jalur resmi."},
{id:"TKP-1787", q:"Di unit Anda sudah jadi kebiasaan berbagi kata sandi sistem antar rekan agar praktis. Sikap Anda ....", opts:[{t:"Menolak ikut serta dan mengusulkan setiap pengguna memakai akun masing-masing", s:5},{t:"Mengingatkan risiko keamanan dari kebiasaan tersebut", s:4},{t:"Ikut berbagi karena sudah biasa", s:3},{t:"Berbagi hanya dengan rekan dekat", s:2},{t:"Menyebarkan kata sandi admin", s:1}], ex:"Berbagi kata sandi menghancurkan akuntabilitas sistem; akun personal adalah prinsip dasar keamanan."},
{id:"TKP-1788", q:"Seseorang meninggalkan flashdisk tak dikenal di meja Anda dengan label dokumen penting. Sikap Anda ....", opts:[{t:"Tidak mencolokkannya dan menyerahkannya ke tim IT untuk pemeriksaan", s:5},{t:"Melaporkan temuan ke atasan atau keamanan", s:4},{t:"Mencolokkan di komputer pribadi untuk mengecek", s:3},{t:"Langsung mencolokkan ke komputer kantor", s:2},{t:"Mengambil datanya untuk kepentingan pribadi", s:1}], ex:"Media asing adalah vektor malware klasik; tidak mencolokkan dan melapor adalah prosedur benar."},
{id:"TKP-1789", q:"Sistem e-office down saat banyak surat mendesak harus diproses. Anda staf administrasi. Sikap Anda ....", opts:[{t:"Beralih ke prosedur manual darurat yang terdokumentasi sambil menginformasikan ke seluruh unit", s:5},{t:"Berkonsultasi dengan tim IT tentang estimasi perbaikan", s:4},{t:"Menunggu sistem pulih tanpa berbuat apa-apa", s:3},{t:"Menolak menerima surat masuk", s:2},{t:"Memalsukan status surat di sistem", s:1}], ex:"Gangguan sistem diatasi dengan prosedur darurat manual yang tertib, bukan kelumpuhan total."},
{id:"TKP-1790", q:"Chatbot layanan instansi Anda memberi informasi keliru kepada warga dan memicu protes. Anda pengelola. Tindakan Anda ....", opts:[{t:"Segera mengoreksi basis pengetahuan chatbot, menyampaikan permohonan maaf resmi, dan menghubungi warga terdampak", s:5},{t:"Mengevaluasi dan memperbaiki jawaban chatbot", s:4},{t:"Menyalahkan vendor pembuat chatbot", s:3},{t:"Menonaktifkan chatbot tanpa penjelasan", s:2},{t:"Membiarkan karena hanya chatbot", s:1}], ex:"Kesalahan layanan digital tetap tanggung jawab instansi; koreksi cepat dan permintaan maaf resmi adalah wajib."},
{id:"TKP-1791", q:"Seorang rekan menyebarkan konten bernada ekstrem di grup WhatsApp kerja. Sikap Anda ....", opts:[{t:"Menegur dan memintanya menghapus, serta melaporkan ke atasan jika berlanjut", s:5},{t:"Mengingatkan bahwa grup kerja bukan tempat konten seperti itu", s:4},{t:"Keluar dari grup diam-diam", s:3},{t:"Membiarkan karena takut konflik", s:2},{t:"Ikut menyebarkan konten tersebut", s:1}], ex:"Konten ekstrem di lingkungan kerja harus ditindak tegas; pembiaran menormalisasi radikalisme."},
{id:"TKP-1792", q:"Anda diajak pengajian eksklusif yang materinya mengarah pada penolakan terhadap negara. Sikap Anda ....", opts:[{t:"Menolak ajakan dan melaporkan indikasi tersebut ke atasan atau aparat berwenang", s:5},{t:"Menolak dengan tegas dan menjaga jarak", s:4},{t:"Menghadiri sekali untuk melihat-lihat", s:3},{t:"Menghadiri karena diajak teman", s:2},{t:"Ikut aktif dalam pengajian tersebut", s:1}], ex:"Ajakan berindikasi radikal harus ditolak dan dilaporkan; rasa penasaran bukan alasan menghadiri."},
{id:"TKP-1793", q:"Audio ceramah provokatif yang menghasut kebencian beredar di kalangan rekan kerja. Sikap Anda ....", opts:[{t:"Tidak ikut menyebarkan dan melaporkan peredaran konten provokatif tersebut", s:5},{t:"Mengingatkan rekan agar tidak terprovokasi", s:4},{t:"Mendengarkan tetapi tidak menanggapi", s:3},{t:"Ikut meneruskan ke grup lain", s:2},{t:"Menyebarkan karena setuju isinya", s:1}], ex:"Konten provokatif dilawan dengan tidak menyebarkan dan melaporkannya."},
{id:"TKP-1794", q:"Seorang rekan memasang atribut organisasi terlarang di ruang kerjanya. Sikap Anda ....", opts:[{t:"Melaporkan temuan tersebut ke atasan dan aparat berwenang sesuai prosedur", s:5},{t:"Menegur rekan dan memintanya melepas atribut", s:4},{t:"Mengabaikan karena urusan pribadi", s:3},{t:"Membiarkan demi menjaga hubungan", s:2},{t:"Ikut memasang atribut serupa", s:1}], ex:"Atribut organisasi terlarang di lingkungan kerja adalah pelanggaran serius yang wajib dilaporkan."},
{id:"TKP-1795", q:"Ditemukan pamflet intoleran yang menolak keberagaman di papan pengumuman kantor. Tindakan Anda ....", opts:[{t:"Mencabut pamflet dan melaporkan ke pimpinan serta keamanan untuk ditelusuri penyebarnya", s:5},{t:"Melaporkan temuan ke atasan", s:4},{t:"Mencabut diam-diam tanpa laporan", s:3},{t:"Membiarkan karena bukan urusan Anda", s:2},{t:"Ikut menyebarkan pamflet tersebut", s:1}], ex:"Propaganda intoleran di fasilitas negara harus dicabut dan ditelusuri penyebarnya."},
{id:"TKP-1796", q:"Seorang rekan menolak hormat kepada simbol negara dengan alasan keyakinan. Sikap Anda ....", opts:[{t:"Menjelaskan kewajiban ASN menghormati simbol negara dan melaporkannya jika tetap menolak", s:5},{t:"Mengingatkannya tentang sumpah dan kewajiban ASN", s:4},{t:"Membiarkan karena hak pribadi", s:3},{t:"Ikut menolak sebagai solidaritas", s:2},{t:"Mendukung penolakannya", s:1}], ex:"Menghormati simbol negara adalah kewajiban ASN yang diucapkan dalam sumpah jabatan."},
{id:"TKP-1797", q:"Ditemukan grafiti berisi propaganda khilafah di fasilitas umum wilayah kerja Anda. Tindakan Anda ....", opts:[{t:"Mengoordinasikan penghapusan segera dan melaporkan ke aparat untuk penelusuran pelaku", s:5},{t:"Melaporkan temuan ke pimpinan dan kepolisian", s:4},{t:"Menghapus sendiri tanpa laporan", s:3},{t:"Membiarkan karena bukan wewenang", s:2},{t:"Menganggapnya sebagai ekspresi biasa", s:1}], ex:"Propaganda anti-NKRI di ruang publik harus dihapus dan ditelusuri pelakunya."},
{id:"TKP-1798", q:"Anda mengetahui seorang pemuda di lingkungan Anda mulai terpapar paham radikal dari media sosial. Sikap Anda ....", opts:[{t:"Melibatkan keluarga dan tokoh masyarakat untuk pendekatan persuasif, serta melaporkan ke aparat jika membahayakan", s:5},{t:"Mengajak dialog dan memberi pemahaman kebangsaan yang benar", s:4},{t:"Membiarkan karena bukan urusan Anda", s:3},{t:"Menjauhi pemuda tersebut", s:2},{t:"Ikut menyebarkan pahamnya", s:1}], ex:"Deradikalisasi dini lewat pendekatan keluarga dan tokoh lebih efektif daripada pengucilan."},
{id:"TKP-1799", q:"Panitia acara kantor mengundang penceramah yang dikenal menyebarkan ujaran kebencian. Anda anggota panitia. Sikap Anda ....", opts:[{t:"Mengusulkan penggantian penceramah dan menjelaskan risikonya kepada panitia", s:5},{t:"Menyampaikan keberatan secara resmi dalam rapat panitia", s:4},{t:"Diam mengikuti keputusan panitia", s:3},{t:"Tetap menghadiri acaranya", s:2},{t:"Mendukung undangan tersebut", s:1}], ex:"Instansi negara tidak boleh memberi panggung kepada penyebar kebencian; keberatan resmi adalah jalan yang benar."},
{id:"TKP-1800", q:"Seorang rekan membagikan konten separatisme di media sosial pribadinya dan Anda mengetahuinya. Sikap Anda ....", opts:[{t:"Melaporkan ke atasan dan aparat berwenang karena ASN dilarang menyebarkan paham separatisme", s:5},{t:"Menegur rekan dan memintanya menghapus konten", s:4},{t:"Mengabaikan karena akun pribadi", s:3},{t:"Memberi like agar tidak bermusuhan", s:2},{t:"Ikut membagikan konten tersebut", s:1}], ex:"ASN terikat larangan menyebarkan separatisme termasuk di akun pribadi; pelanggaran wajib dilaporkan."}
];
